COLLDATA("tadabburar","ar",[[30,"§البقرة\nwords\nثَقِفتُمُوهُموَجَدتُّمُوهُم.\nوَالفِتنَةُأَذىً لِلمُسلِمِينَ، أَو شِركٌ بِاللهِ.\nوَلاَ تُلقُوا بِأَيدِيكُملاَ تُوقِعُوا أَنفُسَكُم.\nالتَّهلُكَةِالهَلاَكِ بِتَركِ الجِهَادِ، وَالإِنفَاقِ فِيهِ.\nأُحصِرتُممُنِعتُم لِمَرَضٍ، أَو عَدُوٍّ.\nالهَديِمَا يُهدَى إِلَى البَيتِ مِنَ الأَنعَامِ.\nنُسُكٍذَبِيحَةٍ: شَاةٍ تُذبَحُ لِفُقَرَاءِ الحَرَمِ.\nحَاضِرِيسَاكِنِي.\ndeeds\nأهد هدية لعائلة أحد المشتغلين في خدمة هذا الدين.\nأحسن اليوم إلى فقير، أو عاجز؛ فإن الله تعالى يحب منك هذا.\nضع خطة مالية وزمنية -ولو طالت مدتها- لجمع تكلفة حج، أو عمرة، مستعينًا بالله -عز وجل-.\nguid\nالإنفاق في سبيل الله أمان للفرد والمجتمع، والإمساك عن النفقة هلاك.\nأتـقن الأعمـال الخيـريـة التي تعملها لتنـال محبة الله تعالى.\nاهتم بإخلاص العبادة لله سبحانه.\nrefl\nوَٱلۡفِتۡنَةُ أَشَدُّ مِنَ ٱلۡقَتۡلِۚ\nأي: فتنة المؤمن عن دينه أشدّ عليه من قتله، وقيل: كفر الكفار أشدّ من قتل المؤمنين لهم في الجهاد. ابن جزي: ١/١٠٠.\nكيف يستدل بهذه الآية على أن حفظ الدين أهم مقاصد الشريعة؟\nوَٱلۡفِتۡنَةُ أَشَدُّ مِنَ ٱلۡقَتۡلِۚ\nولما كان الجهاد فيه إزهاق النفوس وقتل الرجال؛ نبه تعالى على أن ما هم مشتملون عليه من الكفر بالله والشرك به والصد عن سبيله أبلغ وأشدّ وأعظم وأطمّ من القتل؛ ولهذا قال: ﴿وَٱلۡفِتۡنَةُ أَشَدُّ مِنَ ٱلۡقَتۡلِ﴾. ابن كثير: ١/٢١٥-٢١٦.\nما المقصود بالفتنة؟ وما المقصود بالقتل في الآية؟ وأيهما أشد؟\nوَقَٰتِلُوهُمۡ حَتَّىٰ لَا تَكُونَ فِتۡنَةٞ وَيَكُونَ ٱلدِّينُ لِلَّهِۖ\nذكر تعالى المقصود من القتال في سبيله، وأنه ليس المقصود به سفك دماء الكفار، وأخذ أموالهم، ولكن المقصود به أن يكون الدين لله تعالى؛ فيظهر دين الله تعالى على سائر الأديان، ويدفع كل ما يعارضه من الشرك وغيره. السعدي: ٨٩.\nدلت الآية على المراد الحقيقي من قتال الكفار ودفع ما يُتوهم من بعض الناس، وضح ذلك.\nفَمَنِ ٱعۡتَدَىٰ عَلَيۡكُمۡ فَٱعۡتَدُواْ عَلَيۡهِ بِمِثۡلِ مَا ٱعۡتَدَىٰ عَلَيۡكُمۡۚ وَٱتَّقُواْ ٱللَّهَ\nولما كانت النفوس في الغالب لا تقف على حدّها إذا رخص لها في المعاقبة -لطلبها التشفي- أمر تعالى بلزوم تقواه التي هي الوقوف عند حدوده، وعدم تجاوزها. السعدي: ٩٠.\nلماذا أمر سبحانه بالتقوى عند رد العدوان؟\nوَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِينَ ١٩٤\nلما كان في هذه التقوى خروج عن حظ النفس؛ أعلمهم أنه تعالى يكون عوضًا لهم من أنفسهم بما اتقوا وداوموا على التقوى، حتى كانت وصفًا لهم، فأعلمهم بصحبته لهم. البقاعي: ١/٣٦٧.\nما سبب معية الله للمتقين في الآية؟\nوَأَنفِقُواْ فِي سَبِيلِ ٱللَّهِ وَلَا تُلۡقُواْ بِأَيۡدِيكُمۡ إِلَى ٱلتَّهۡلُكَةِ\nقال أبو أيوب -رضي الله عنه-: \"نزلت فينا معشر الأنصار؛ وذلك أن الله تعالى لمَّا أعز دينه، ونصر رسوله قلنا فيما بيننا: إنا قد تركنا أهلنا وأموالنا حتى فشا الإسلام، ونصر الله نبيه، فلو رجعنا إلى أهلينا وأموالنا فأقمنا فيها، فأصلحنا ما ضاع منها، فأنزل الله تعالى: ﴿وَأَنفِقُواْ فِي سَبِيلِ ٱللَّهِ وَلَا تُلۡقُواْ بِأَيۡدِيكُمۡ إِلَى ٱلتَّهۡلُكَةِ﴾؛ فالتهلكة: الإقامة في الأهل والمال، وترك الجهاد\". البغوي: ١/١٧١.\nما المقصود بالتهلكة؟\nوَأَنفِقُواْ فِي سَبِيلِ ٱللَّهِ وَلَا تُلۡقُواْ بِأَيۡدِيكُمۡ إِلَى ٱلتَّهۡلُكَةِ وَأَحۡسِنُوٓاْۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُحۡسِنِينَ ١٩٥\nلما كانت النفقة من أعظم دعائم الجهاد، وكان العيش في أول الإسلام ضيقًا والمال قليلًا؛ فكان ذلك موجبًا لكل أحد أن يتمسك بما في يده، ظنًا أن في التمسك به النجاة، وفي إنفاقه الهلاك؛ أخبرهم أن الأمر على غير ما يسوّل به الشيطان من ذلك؛ ﴿ٱلشَّيۡطَٰنُ يَعِدُكُمُ ٱلۡفَقۡرَ﴾ [البقرة: ٢٦٨]. البقاعي: ١/٣٦٧.\nبِمَ تكون النجاة، وبِمَ يكون الهلاك إذا دعا داعي الجهاد؟"],[31,"§البقرة\nwords\nأَشهُرٌ مَعلُومَاتٌهِيَ: شَوَّالٌ، وَذُو القَعدَةِ، وَعَشرٌ مِن ذِي الحِجَّةِ.\nرَفَثَالجِمَاعَ وَمُقَدِّمَاتِهِ القَولِيَّةَ وَالفِعلِيَّةَ.\nفَضلًارِزقًا بِالتِّجَارَةِ.\nأَفَضتُم مِن عَرَفَاتٍدَفَعتُم بَعدَ غُرُوبِ الشَّمسِ، رَاجِعِينَ مِن عَرَفَاتٍ.\ndeeds\nاستعن بالله تعالى، وضع خطة زمنية مالية توفر فيها احتياجاتك المالية، وتكف بها نفسك عن ذلّ السؤال، مع الحرص على ألا تشغلك عن أوامر الله تعالى.\nاستغفر اليوم بعد كل عبادة وعمل صالح؛ اعترافًا بالتقصير، وجبرًا للنقص، واجعلها صفةً دائمةً لك.\nأكثر اليوم من الدعاء الوارد في الآية الكريمة.\nguid\nالمدركون لمقاصد العبادات هم الأحسن علمًا وتربيةً وخلقًا.\nكما تهتم بالأسباب المادية -كالطعام والشراب- اهتم بالأسباب الشرعية؛ كصلاح القلب وتقواه.\nلا تحقرن من المعروف شيئًا مهما صغُر؛ فالصغير في عينك قد يكون كبيرًا عند الله سبحانه.\nrefl\nٱلۡحَجُّ أَشۡهُرٞ مَّعۡلُومَٰتٞۚ فَمَن فَرَضَ فِيهِنَّ ٱلۡحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي ٱلۡحَجِّۗ\nقال الحسن: \"الحج المبرور هو أن يرجع صاحبه زاهدًا في الدنيا، راغبًا في الآخرة\". القرطبي: ٣/٣٢٤\nكيف يكون حج المؤمن مبرورًا؟\nفَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي ٱلۡحَجِّۗ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ يَعۡلَمۡهُ ٱللَّهُۗ\nتحريض وحث على حسن الكلام مكان الفحش، وعلى البر والتقوى في الأخلاق مكان الفسوق والجدال. القرطبي: ٣/٣٢٨.\nبيِّن عناية القرآن الكريم بالكلمة الطيبة، والبعد عن الكلام السيئ.\nوَتَزَوَّدُواْ فَإِنَّ خَيۡرَ ٱلزَّادِ ٱلتَّقۡوَىٰۖ وَٱتَّقُونِ يَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ ١٩٧\nوخص -جل ذكره- بالخطاب بذلك أولي الألباب؛ لأنهم هم أهل التمييز بين الحق والباطل، وأهل الفكر الصحيح والمعرفة بحقائق الأشياء التي بالعقول تُدرك وبالألباب تُفهم، ولم يجعل لغيرهم من أهل الجهل في الخطاب بذلك حظًّا. الطبري: ٤/١٦١.\nلِمَّ خص الله تعالى أولي الألباب بالأمر بتقواه؟\nوَتَزَوَّدُواْ فَإِنَّ خَيۡرَ ٱلزَّادِ ٱلتَّقۡوَىٰۖ وَٱتَّقُونِ يَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ ١٩٧\nنزلت الآية في طائفة من العرب كانت تجيء إلى الحج بلا زاد، ويقول بعضهم: نحن المتوكلون، ويقول بعضهم: كيف نحج بيت الله ولا يطعمنا؟ فكانوا يبقَون عالةً على الناس، فنُهوا عن ذلك، وأُمروا بالتزود. ابن عطية: ١/٢٧٣.\nمن ترك السبب فليس بمتوكل، وضح ذلك من خلال الآية.\nلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَبۡتَغُواْ فَضۡلٗا مِّن رَّبِّكُمۡۚ\nلمَّا نهى عن الجدال في الحج؛ كان مظنةً للنهي عن التجارة فيه أيضًا؛ لكونها مفضية -في الأغلب- إلى النزاع في قلة القيمة وكثرتها؛ فعقَّب ذلك بذكر حكمها. الألوسي: ٢/٨٧.\nلماذا بيَّن تعالى جواز التجارة في الحج بعد النهي عن الجدال؟\nفَإِذَا قَضَيۡتُم مَّنَٰسِكَكُمۡ فَٱذۡكُرُواْ ٱللَّهَ كَذِكۡرِكُمۡ ءَابَآءَكُمۡ أَوۡ أَشَدَّ ذِكۡرٗاۗ فَمِنَ ٱلنَّاسِ مَن يَقُولُ رَبَّنَآ ءَاتِنَا\nوقرن سبحانه الذكر بالدعاء؛ للإشارة إلى أن المعتبر من الذكر ما يكون عن قلب حاضر، وتوجه باطن؛ كما هو حال الداعي حين طلب حاجة، لا مجرد التفوه والنطق به،... وبدأ -سبحانه وتعالى- بالذكر لكونه مفتاحًا للإجابة، ثم بين -جل شأنه- أنهم ينقسمون في سؤال الله تعالى إلى من يغلب عليه حب الدنيا؛ فلا يدعو إلا بها، ومن يدعو بصلاح حاله في الدنيا والآخرة. الألوسي: ٢/٩٠.\nلماذا قرن سبحانه الذكر بالدعاء؟ ولماذا بدأ بالذكر؟\nأُوْلَٰٓئِكَ لَهُمۡ نَصِيبٞ مِّمَّا كَسَبُواْۚ وَٱللَّهُ سَرِيعُ ٱلۡحِسَابِ ٢٠٢\nقيل لعلي -رضي الله عنه-: كيف يُحاسب الله الناس على كثرتهم؟ قال: \"كما يرزقهم على كثرتهم\". ابن جزي: ١/١٠٣.\nكيف يحاسب الله الخلق على كثرتهم؟"],[32,"§البقرة\nwords\nأَلَدُّ الخِصَامِشَدِيدُ العَدَاوَةِ وَالخُصُومَةِ.\nفَحَسبُهُكَافِيهِ.\nالمِهَادُالفِرَاشُ، وَالمَضجَعُ.\nظُلَلٍ مِنَ الغَمَامِقِطَعٍ مِنَ السَّحَابِ.\ndeeds\nتقويمنا للآخرين يقع بين إفراط وتفريط، تشاور أنت ومن حولك، ثم اكتبوا قواعد مفيدة في تقويم الآخرين.\nحدد اسمًا معاصرًا تظن أنه ممن شرى نفسه ابتغاء مرضاة الله، ثم تأمل سيرته.\nتذكر معصية وقعت منك أكثر من مرة، ثم حدد خطوات الشيطان عليك فيها لتكـون أكثر حذرًا من أول خطواته.\nguid\nالكبر مانع من قبول النصيحة، فأكثر من الاستعاذة والتحذير منه.\nكن ممن باع نفسه ووقته ابتغاء مرضاة الله تعالى، وطمعًا في جنته.\nاحذر الشيطان ووساوسه، وتذكر دائمًا أن له خطوات يستدرج بها المؤمن فأكثر من الاستعاذة بالله منه.\nrefl\nوَمِنَ ٱلنَّاسِ مَن يُعۡجِبُكَ قَوۡلُهُۥ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَيُشۡهِدُ ٱللَّهَ عَلَىٰ مَا فِي قَلۡبِهِۦ وَهُوَ أَلَدُّ ٱلۡخِصَامِ ٢٠٤\nوفي الآية إشارة إلى أن شدة المخاصمة مذمومة؛ عن النبي -صلى الله عليه وسلم-: «أبغض الرجال إلى الله تعالى الألد الخصم». وشدة الخصومة من صفات المنافقين؛ لأنهم يحبون الدنيا؛ فيكثرون الخصام عليها. الألوسي: ٢/٩٥.\nالخصومة جائزة، والشدة فيها مذمومة، وضح ذلك من خلال الآية.\nوَمِنَ ٱلنَّاسِ مَن يُعۡجِبُكَ قَوۡلُهُۥ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَيُشۡهِدُ ٱللَّهَ عَلَىٰ مَا فِي قَلۡبِهِۦ وَهُوَ أَلَدُّ ٱلۡخِصَامِ ٢٠٤ وَإِذَا تَوَلَّىٰ سَعَىٰ فِي ٱلۡأَرۡضِ لِيُفۡسِدَ فِيهَا وَيُهۡلِكَ ٱلۡحَرۡثَ وَٱلنَّسۡلَۚ وَٱللَّهُ لَا يُحِبُّ ٱلۡفَسَادَ ٢٠٥\nففي هذه الآية دليل على أن الأقوال التي تصدر من الأشخاص ليست دليلًا على صدق ولا كذب، ولا بر ولا فجور؛ حتى يوجد العمل المصدق لها، المزكي لها، وأنه ينبغي اختبار أحوال الشهود والمحقّ والمبطل من الناس بسبر أعمالهم، والنظر لقرائن أحوالهم، وأن لا يغتر بتمويههم، وتزكيتهم أنفسهم. السعدي: ٩٤.\nما الاختبار الحقيقي لمصداقية كلام للناس؟\nوَمِنَ ٱلنَّاسِ مَن يُعۡجِبُكَ قَوۡلُهُۥ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَيُشۡهِدُ ٱللَّهَ عَلَىٰ مَا فِي قَلۡبِهِۦ وَهُوَ أَلَدُّ ٱلۡخِصَامِ ٢٠٤\nوفي هذه الآية دليل وتنبيه على الاحتياط فيما يتعلق بأمور الدين والدنيا، واستبراء أحوال الشهود والقضاة، وأن الحاكم لا يعمل على ظاهر أحوال الناس وما يبدو من إيمانهم وصلاحهم حتى يبحث عن باطنهم؛ لأن الله تعالى بيّن أحوال الناس، وأن منهم من يُظهر قولًا جميلًا، وهو ينوي قبيحًا. القرطبي: ٣/٣٨٣.\nتعود كثير من أخطائنا إلى الخطأ في تقويم الناس، وقد حذرتنا الآية من ذلك، وضح ذلك.\nوَإِذَا تَوَلَّىٰ سَعَىٰ فِي ٱلۡأَرۡضِ لِيُفۡسِدَ فِيهَا وَيُهۡلِكَ ٱلۡحَرۡثَ وَٱلنَّسۡلَۚ وَٱللَّهُ لَا يُحِبُّ ٱلۡفَسَادَ ٢٠٥\n﴿وَإِذَا تَوَلَّىٰ﴾: انصرف عمّن خدعه بكلامه، (سَعى): مشى في الأرضِ لِيُفسِدَ فِيها؛ بإدخال الشُّبَه في قلوب المسلمين، وباستخراج الحيل في تقوية الكفر. القاسمي: ١/٨٢.\nمن الحكمة الربط بين أقوال الرجل وأفعاله، بيِّن ذلك من الآية.\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱدۡخُلُواْ فِي ٱلسِّلۡمِ كَآفَّةٗ وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ\n﴿ٱدۡخُلُواْ فِي ٱلسِّلۡمِ كَآفَّةً﴾؛ أي: في جميع شرائع الدين، ولا يتركوا منها شيئًا، وأن لا يكونوا ممن اتخذ إلهه هواه: إن وافق الأمر المشروع هواه فعله، وإن خالفه تركه، بل الواجب أن يكون الهوى تبعًا للدين، وأن يفعل كل ما يقدر عليه من أفعال الخير. السعدي: ٩٤.\nلماذا أمرنا بالدخول في السلم كافة؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱدۡخُلُواْ فِي ٱلسِّلۡمِ كَآفَّةٗ وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ\nولما كان الدخول في السلم كافة لا يمكن ولا يتصور إلا بمخالفة طرق الشيطان، قال: ﴿وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِ﴾. السعدي: ٩٤.\nلماذا أمر بعدم اتباع خطوات الشيطان بعد الأمر بالدخول في السلم كافة؟\nفَإِن زَلَلۡتُم مِّنۢ بَعۡدِ مَا جَآءَتۡكُمُ ٱلۡبَيِّنَٰتُ فَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ ٢٠٩\nوفي الآية دليل على أن عقوبة العالم بالذنب أعظم من عقوبة الجاهل به. القرطبي: ٣/٣٩٥.\nعبادة العالم أعظم من غيره، ومعصية العالم أعظم من غيره، وضح ذلك من الآية."],[33,"§البقرة\nwords\nالبَأسَاءُالفَقرُ.\nوَالضَّرَّاءُالمَرَضُ.\ndeeds\nأرسل رسالة تبين فيها أن لباس النساء المتبرج من كفر النعمة.\nاحمد الله كثيرًا على إنزال القرآن وحفظه؛ فبحفظه بقي الدين ثابتًا، ولم يُحرَّف كما حُرِّفت الديانات الأخرى.\nزر مسلمًا نزل به ابتلاء، وذكره أنه لا يبتلى إلا المؤمن، وأن عاقبة الابتلاء الجنة.\nguid\nالثبات على الدين والقيم والمبادئ أمان للفرد والمجتمع.\nبداية خذلان الأمة وتعرضها للخسارة والدمار أن تختلف في كتابها ودينها طلبًا للرئاسة، وجريًا وراء الأهواء أو العصبيات.\nالتحذير من طغيان محبة زينة الحياة الدنيا، واستيلائها على القلب.\nrefl\nسَلۡ بَنِيٓ إِسۡرَٰٓءِيلَ كَمۡ ءَاتَيۡنَٰهُم مِّنۡ ءَايَةِۢ بَيِّنَةٖۗ وَمَن يُبَدِّلۡ نِعۡمَةَ ٱللَّهِ مِنۢ بَعۡدِ مَا جَآءَتۡهُ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ ٢١١\nأصل هذا التبديل: رد علم العالم عليه ورد صلاح الصالح إليه، وعدم الاقتداء بعلم العالم والاهتداء بصلاح الصالح. البقاعي: ١/٣٩٠.\nما أصل التبديل في الآية؟\nوَمَن يُبَدِّلۡ نِعۡمَةَ ٱللَّهِ مِنۢ بَعۡدِ مَا جَآءَتۡهُ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ ٢١١\nمن أنعم الله عليه بنعمةٍ دينية أو دنيوية فلم يشكرها، ولم يقم بواجبها اضمحلت عنه وذهبت، وتبدلت بالكفر والمعاصي، فصار الكفر بدل النعمة، وأمَّا من شكر الله تعالى وقام بحقها فإنها تثبت وتستمر، ويزيده الله منها. السعدي: ٩٥.\nكيف تثبت النعم؟ وكيف تزول؟\nزُيِّنَ لِلَّذِينَ كَفَرُواْ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَيَسۡخَرُونَ مِنَ ٱلَّذِينَ ءَامَنُواْۘ وَٱلَّذِينَ ٱتَّقَوۡاْ فَوۡقَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ\nيسخرون بمن تبعك من أهل الإيمان والتصديق بك في تركهم المكاثرة والمفاخرة بالدنيا وزينتها من الرياش والأموال؛ بطلب الرياسات، وإقبالهم على طلبهم ما عندي برفض الدنيا، وترك زينتها. الطبري: ٤/٢٧٣.\nما مقاييس أهل الدنيا للفوز والفلاح؟\nفَهَدَى ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ لِمَا ٱخۡتَلَفُواْ فِيهِ مِنَ ٱلۡحَقِّ بِإِذۡنِهِۦۗ وَٱللَّهُ يَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٍ ٢١٣\nعن عائشة أنّ النبيّ -صلى الله عليه وسلم- كان إذا قام يُصلّي من اللّيل يقول: «اللهمّ ربّ جبريل وميكائيل وإسرافيل، فاطرَ السموات والأرض، عالم الغيب والشهادة، أنت تحكم بين عبادك فيما كانوا فيه يختلفون، اهدني لما اختُلف فيه من الحقّ بإذنك؛ إنّك تهدي من تشاء إلى صراط مستقيم». ابن تيمية: ١/٤٩٣.\nكان -صلى الله عليه وسلم- يطلب الهداية من الله فيما اختلف فيه، فما دعاؤه؟\nأَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُواْ ٱلۡجَنَّةَ وَلَمَّا يَأۡتِكُم مَّثَلُ ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلِكُمۖ مَّسَّتۡهُمُ ٱلۡبَأۡسَآءُ وَٱلضَّرَّآءُ وَزُلۡزِلُواْ حَتَّىٰ يَقُولَ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ مَتَىٰ نَصۡرُ ٱللَّهِۗ أَلَآ إِنَّ نَصۡرَ ٱللَّهِ قَرِيبٞ ٢١٤\n﴿أَمۡ حَسِبۡتُمۡ﴾: خطاب للمؤمنين على وجه التشجيع لهم والأمر بالصبر على الشدائد. ﴿وَلَمَّا يَأۡتِكُم﴾؛ أي: لا تدخلوا الجنة حتى يصيبكم مثل ما أصاب من كان قبلكم. ابن جزي: ١/١٠٧.\nمن خلال فهمك للآية، ما شرط دخول الجنة؟\nأَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُواْ ٱلۡجَنَّةَ وَلَمَّا يَأۡتِكُم مَّثَلُ ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلِكُمۖ مَّسَّتۡهُمُ ٱلۡبَأۡسَآءُ وَٱلضَّرَّآءُ وَزُلۡزِلُواْ حَتَّىٰ يَقُولَ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ مَتَىٰ نَصۡرُ ٱللَّهِۗ أَلَآ إِنَّ نَصۡرَ ٱللَّهِ قَرِيبٞ ٢١٤\nإعلام بأن الله -سبحانه وتعالى- إنَّما يفرج عن أنبيائه ومن معهم بعد انقطاع أسبابهم ممن سواه؛ ليمتحن قلوبهم للتقوى؛ فتتقدس سرائرهم من الركون لشيء من الخلق، وتتعلق ضمائرهم بالله تعالى وحده. البقاعي: ١/٣٩٧.\nلماذا يتأخر النصر أحيانًا؟ وضح ذلك من خلال الآية.\nيَسۡٔلُونَكَ مَاذَا يُنفِقُونَۖ قُلۡ مَآ أَنفَقۡتُم مِّنۡ خَيۡرٖ فَلِلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱبۡنِ ٱلسَّبِيلِۗ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٞ ٢١٥\nختم بالعلم؛ لأجل دخول الخلل على النيات في الإنفاق؛ لأنه من أشد شيء تتباهى به النفس، فيكاد لا يسلم لها منه إلا ما لا تعلمه شمالها. البقاعي: ١/٤٠٠.\nما دلالة ختم الآية بصفة العلم لله سبحانه؟"],[34,"§البقرة\nwords\nوَالفِتنَةُالشِّركُ.\nوَالمَيسِرِالقِمَارِ، وَهُوَ أَخذُ المَالِ، أَو إِعطَاؤُهُ بِطَرِيقِ المُغَالَبَاتِ الَّتِي فِيهَا عِوَضٌ مِنَ الطَّرَفَينِ.\ndeeds\nتذكر شيئًا تعلقت به نفسك فصرفه الله عنك، أو كرهته فقُدِّر عليك، واحمد الله؛ فقد يكون في ذلك خير لك.\nاكتب ثلاث فوائد من هذه الآية القرآنية العظيمة.\nكرر اليوم هذا الدعاء: \"يا مقلب القلوب ثبت قلبي على دينك\".\nguid\nالجهاد في سبيل الله شريعة ماضية إلى يوم القيامة.\nالمسلم الصادق يسلم أمره لله؛ ولو خالف هواه.\nالسبب الأول للحرب على بلاد المسلمين هو الدين؛ مهما لبسوا الحرب بلباس آخر.\nrefl\nكُتِبَ عَلَيۡكُمُ ٱلۡقِتَالُ وَهُوَ كُرۡهٞ لَّكُمۡۖ وَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡٔاً وَهُوَ خَيۡرٞ لَّكُمۡۖ وَعَسَىٰٓ أَن تُحِبُّواْ شَيۡٔاً وَهُوَ شَرّٞ لَّكُمۡۚ\nهذا الكره من حيث نفور الطبع عنه؛ لما فيه من مؤنة المال، ومشقة النفس، وخطر الروح، لا أنهم كرهوا أمر الله تعالى. البغوي: ١/٢٠٣.\nكيف يكون القتال في سبيل الله تعالى مكروهًا للمؤمنين؟\nوَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡٔاً وَهُوَ خَيۡرٞ لَّكُمۡۖ\nلأن القتال يعقبه النصر والظفر على الأعداء، والاستيلاء على بلادهم وأموالهم وذرياتهم وأولادهم. ابن كثير: ١/٢٣٩.\nكيف يكون القتال خيرًا مع أن ظاهره المشقة والألم؟\nوَعَسَىٰٓ أَن تُحِبُّواْ شَيۡٔاً وَهُوَ شَرّٞ لَّكُمۡۚ\nالقعود عن القتال قد يعقبه استيلاء العدو على البلاد والحكم. ابن كثير: ١/٢٣٩.\nقد يفرح المجتمع بترك القتال، ويكون ذلك شرًّا له؛ فكيف ذلك؟\nيَسۡٔلُونَكَ عَنِ ٱلشَّهۡرِ ٱلۡحَرَامِ قِتَالٖ فِيهِۖ قُلۡ قِتَالٞ فِيهِ كَبِيرٞۚ وَصَدٌّ عَن سَبِيلِ ٱللَّهِ وَكُفۡرُۢ بِهِۦ وَٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَإِخۡرَاجُ أَهۡلِهِۦ مِنۡهُ أَكۡبَرُ عِندَ ٱللَّهِۚ وَٱلۡفِتۡنَةُ أَكۡبَرُ مِنَ ٱلۡقَتۡلِۗ\nإن كان قتل النفوس فيه شر، فالفتنة الحاصلة بالكفر وظهور أهله أعظم من ذلك؛ فيدفع أعظم الفسادين بالتزام أدناهما. ابن تيمية: ١/٥٠١.\nسير المجتمع إلى الكفر، أو سيره إلى الجهاد، أيهما أعظم مفسدة؟\nإِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَاجَرُواْ وَجَٰهَدُواْ فِي سَبِيلِ ٱللَّهِ أُوْلَٰٓئِكَ يَرۡجُونَ رَحۡمَتَ ٱللَّهِۚ\nإشارة إلى أن العبد -ولو أتى من الأعمال بما أتى به- لا ينبغي له أن يعتمد عليها ويعول عليها، بل يرجو رحمة ربه، ويرجو قبول أعماله ومغفرة ذنوبه وستر عيوبه. السعدي: ٩٨.\nفي الآية تنبيهٌ عظيم لأصحاب الأعمال الصالحة، فما هو؟\nإِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَاجَرُواْ وَجَٰهَدُواْ فِي سَبِيلِ ٱللَّهِ أُوْلَٰٓئِكَ يَرۡجُونَ رَحۡمَتَ ٱللَّهِۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ٢١٨\nوإنَّما قال (يرجون) وقد مدحهم؛ لأنه لا يعلم أحد في هذه الدنيا أنه صائر إلى الجنة ولو بلغ في طاعة الله كل مبلغ؛ لأمرين: أحدهما: لا يدري بما يختم له، والثاني: لئلَّا يتكل على عمله. القرطبي: ٣/٤٣٢.\nلماذا قال سبحانه: (يرجون) -وهي صيغة محتملة- مع أن أعمالهم عظيمة؟\nكَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَتَفَكَّرُونَ ٢١٩\nأي في الآيات، فتسنتنبطوا الأحكام منها، وتفهموا المصالح والمنافع المنوطة بها؛ فترجّي التفكر غاية لتبيين الآيات، فتأخذون بالأصلح وتجتنبون عمَّا يضركم ولا ينفعكم، أو يضركم أكثر مما ينفعكم. الألوسي: ٢/١١٦.\nما فائدة التفكر في آيات القرآن؟"],[35,"§البقرة\nwords\nلأَعنَتَكُملَضَيَّقَ عَلَيكُم.\nحَرثٌ لَكُممَوضِعُ زَرعٍ لَكُم، تَضَعُونَ النُّطفَةَ فِي أَرحَامِهِنَّ فَيَحمِلنَ.\nأَنَّىكَيفَ أَرَدتُّم، مَا دَامَ ذَلِكَ فِي مَوضِعِ الحَرثِ؛ وَهُوَ الفَرجُ.\nعُرضَةًمَانِعًا.\ndeeds\nأكرم يتيمًا، أو اسعَ في كفالته.\nيختبر الله سبحانه كل مجتمع بإيجاد دعاة إلى الخير، ودعاة إلى الشر، فحدد دعاة الخير في مجتمعك، واسعَ في مساعدتهم، والدعاء لهم.\nجدد وضوءك اليوم لكل صلاة؛ ولو كنت على وضوء.\nguid\nسؤال الموثوقين عن أحكام الأموال وحفظ الحقوق سمة من سمات المتقين المفلحين.\nوصية الله سبحانه للمؤمن أن يبحث عن الزوجة المؤمنة صاحبة الدين.\nالإسلام عنوان النظافة والطهر، وقد بيّن أدق تفاصيل الطهارة في كتابه الكريم.\nrefl\nوَلَا تَنكِحُواْ ٱلۡمُشۡرِكَٰتِ حَتَّىٰ يُؤۡمِنَّۚ وَلَأَمَةٞ مُّؤۡمِنَةٌ خَيۡرٞ مِّن مُّشۡرِكَةٖ وَلَوۡ أَعۡجَبَتۡكُمۡۗ وَلَا تُنكِحُواْ ٱلۡمُشۡرِكِينَ حَتَّىٰ يُؤۡمِنُواْۚ وَلَعَبۡدٞ مُّؤۡمِنٌ خَيۡرٞ مِّن مُّشۡرِكٖ وَلَوۡ أَعۡجَبَكُمۡۗ أُوْلَٰٓئِكَ يَدۡعُونَ إِلَى ٱلنَّارِۖ\n﴿أُوْلَٰٓئِكَ يَدۡعُونَ إِلَى ٱلنَّارِۖ﴾؛ أي: في أقوالهم أو أفعالهم وأحوالهم؛ [فمُخالِطهم] على خطر منهم، والخطر ليس من الأخطار الدنيوية، إنَّما هو من الشقاء الأبدي. ويستفاد من تعليل الآية: النهي عن مخالطة كل مشرك ومبتدع؛ لأنه إذا لم يجز التزوُّج مع أن فيه مصالح كثيرة فالخلطة المجردة من باب أولى، وخصوصًا الخلطة التي فيها ارتفاع المشرك ونحوه على المسلم. السعدي: ٩٩.\nكيف تستفيد من الآية خطورة مخالطة المسلم للمبتدعة والمشركين؟\nأُوْلَٰٓئِكَ يَدۡعُونَ إِلَى ٱلنَّارِۖ وَٱللَّهُ يَدۡعُوٓاْ إِلَى ٱلۡجَنَّةِ وَٱلۡمَغۡفِرَةِ بِإِذۡنِهِۦۖ وَيُبَيِّنُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمۡ يَتَذَكَّرُونَ ٢٢١\nالمقصود من الآية أن المؤمن يجب أن يكون حذِرًا عمَّا يضره في الآخرة، وأن لا يحوم حول حمى ذلك، ويتجنب عمَّا فيه الاحتمال؛ مع أن النفس والشيطان يعاونان على ما يؤدي إلى النار. الألوسي: ٢/١٢٠.\nمتى يكون المسلم أكثر عرضة للهلاك؟\nإِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ وَيُحِبُّ ٱلۡمُتَطَهِّرِينَ ٢٢٢\nتأنيسًا لقلوب المتحرجين من معاودة الذنب بعد توبة منه، أي: ومن معاودة التوبة بعد الوقوع في ذنب ثان؛ لما يخشى العاصي من أن يُكتب عليه كذبة كلما أحدث توبة وزل بعدها؛ فيُعد مستهزئًا، فيسقط من عين الله ثم لا يبالي به، فيوقفه ذلك عن التوبة. البقاعي: ١/٤٢٢.\nلماذا عبر بصيغة التوابين التي تفيد الاستمرار ؟\nوَبَشِّرِ ٱلۡمُؤۡمِنِينَ ٢٢٣\nلم يذكر المُبَشَّر به ليدل على العموم، وأن لهم البشرى في الحياة الدنيا وفي الآخرة، وكل خير واندفاع كل ضير رُتِّب على الإيمان؛ فهو داخل في هذه البشارة. السعدي: ١٠٠.\nلماذا لم يذكر الله المُبَشَّر به في هذه الآية؟\nوَلَا تَجۡعَلُواْ ٱللَّهَ عُرۡضَةٗ لِّأَيۡمَٰنِكُمۡ\nالمعنى: لا تستكثروا من اليمين بالله؛ فإنه أهيب للقلوب؛ قال تعالى: ﴿وَٱحۡفَظُوٓاْ أَيۡمَٰنَكُمۡ﴾ [المائدة:٨٩]، وذم من كثر اليمين؛ فقال: ﴿وَلَا تُطِعۡ كُلَّ حَلَّافٖ مَّهِينٍ﴾ [القلم: ١٠]. القرطبي: ٤/١٣.\nما فائدة التقليل من الحلف واليمين؟\nوَلَا تَجۡعَلُواْ ٱللَّهَ عُرۡضَةٗ لِّأَيۡمَٰنِكُمۡ أَن تَبَرُّواْ وَتَتَّقُواْ وَتُصۡلِحُواْ بَيۡنَ ٱلنَّاسِۚ وَٱللَّهُ سَمِيعٌ عَلِيمٞ ٢٢٤\nنهاهم الله أن يجعلوا الحلف بالله مانعًا لهم من فعل ما أمر به؛ لئلَّا يمتنعوا عن طاعته باليمين التي حلفوها. ابن تيمية: ١/٥١٧.\nمتى يكون الحلف واليمين مذموما؟\nوَلَا تَجۡعَلُواْ ٱللَّهَ عُرۡضَةٗ لِّأَيۡمَٰنِكُمۡ أَن تَبَرُّواْ وَتَتَّقُواْ وَتُصۡلِحُواْ بَيۡنَ ٱلنَّاسِۚ وَٱللَّهُ سَمِيعٌ عَلِيمٞ ٢٢٤\nثم ختم الآية بهذين الاسمين الكريمين، فقال: ﴿وَٱللَّهُ سَمِيعٌ﴾؛ أي: لجميع الأصوات، (عليم) بالمقاصد والنيات؛ ومنه سماعه لأقوال الحالفين، وعلمه بمقاصدهم هل هي خير أم شر، وفي ضمن ذلك التحذير من مجازاته، وأن أعمالكم ونياتكم قد استقر علمها عنده. السعدي: ١٠٠-١٠١.\nختام الآية بين عظم اليمين وأهميتها، وضح ذلك."],[36,"§البقرة\nwords\nبِاللَّغوِ فِي أَيمَانِكُماليَمِينُ اللاَّغِيَةُ هِيَ: اليَمِينُ الَّتِي لاَ يَقصِدُهَا صَاحِبُهَا.\nيُؤلُونَيَحلِفُونَ أَلاَّ يُجَامِعُوا نِسَاءَهُم.\nتَرَبُّصُانتِظَارُ.\nفَاءُوارَجَعُوا.\nيَتَرَبَّصنَيَنتَظِرنَ.\nثَلاَثَةَ قُرُوءٍثَلاَثَ حِيَضٍ.\ndeeds\nلا تـحلف يمينًا هذا اليوم؛ تعـظيمًا لله -عز وجل-.\nاشتر اليوم هدية، وقدمها لزوجتك، أو أعطها والدك ليقدمها لوالدتك باسمه.\nأرسل رسالة تحذر فيها من التحريف في حقوق المرأة، ثم اتخاذها ذريعة لإفسادها من قبل المنافقين ومن خُدِع بمنهجهم.\nguid\nمن حكم العدة أن الزوجين يختبران فيها عواطفهما ومصالحهما قبل الفرقة.\nلكل من الزوجين حقوق وواجبات لا تسعد الأسرة إلا بتحقيقها جميعًا.\nللرجل منزلة زائدة على المرأة؛ فمن زعم أنهما متساويان فقد أخطأ وخالف كلام خالقهما الأعلم بحالهما.\nrefl\nلَّا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغۡوِ فِيٓ أَيۡمَٰنِكُمۡ وَلَٰكِن يُؤَاخِذُكُم بِمَا كَسَبَتۡ قُلُوبُكُمۡۗ وَٱللَّهُ غَفُورٌ حَلِيمٞ ٢٢٥\nوالشارع لم يرتب المؤاخذة إلا على ما يكسبه القلب من الأقوال والأفعال الظاهرة؛ كما قال: ﴿وَلَٰكِن يُؤَاخِذُكُم بِمَا كَسَبَتۡ قُلُوبُكُمۡ﴾، ولم يؤاخذ على أقوال وأفعال لم يعلم بها القلب، ولم يتعمدها، وكذلك ما يحدث به المرء نفسه؛ لم يؤاخذ منه إلا بما قاله، أو فعله. ابن تيمية: ١/٥١٧.\nمتى يحاسب الإنسان على تصرفاته؟ وضح ذلك من خلال الآية.\nلَّا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغۡوِ فِيٓ أَيۡمَٰنِكُمۡ وَلَٰكِن يُؤَاخِذُكُم بِمَا كَسَبَتۡ قُلُوبُكُمۡۗ وَٱللَّهُ غَفُورٌ حَلِيمٞ ٢٢٥\nلا يعاجلهم بالأخذ. والحلم احتمال الأعلى للأذى من الأدنى. البقاعي: ١/٤٢٦.\nما دلالة ختم الآية بـــ صفة الله الحليم سبحانه؟\nوَلَهُنَّ مِثۡلُ ٱلَّذِي عَلَيۡهِنَّ بِٱلۡمَعۡرُوفِۚ وَلِلرِّجَالِ عَلَيۡهِنَّ دَرَجَةٞۗ\nقال ابن عباس -رضي الله عنهما-: \"إني أحب أن أتزين لامرأتي كما تحب امرأتي أن تتزين لي؛ لأن الله تعالى يقول: ﴿وَلَهُنَّ مِثۡلُ ٱلَّذِي عَلَيۡهِنَّ بِٱلۡمَعۡرُوفِ﴾\". البغوي: ١/٢٢٥.\nلم يُرِد الشرع دفع أسباب الطلاق فقط؛ بل أراد وجود السعادة بين الزوجين، وضح ذلك.\nوَلَهُنَّ مِثۡلُ ٱلَّذِي عَلَيۡهِنَّ بِٱلۡمَعۡرُوفِۚ وَلِلرِّجَالِ عَلَيۡهِنَّ دَرَجَةٞۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ ٢٢٨\nما يوجبه العقد لكل واحد من الزوجين على الآخر... ليس بمقدر؛ بل المرجع في ذلك إلى العرف؛ كما دل عليه الكتاب في مثل قوله تعالى: ﴿وَلَهُنَّ مِثۡلُ ٱلَّذِي عَلَيۡهِنَّ بِٱلۡمَعۡرُوفِ﴾. ابن تيمية: ١/٥٢٣.\nما المعتبر في مقدار حقوق الزوجية؟\nوَلِلرِّجَالِ عَلَيۡهِنَّ دَرَجَةٞۗ\nولا يخفى على لبيب فضل الرجال على النساء؛ ولو لم يكن إلا أن المرأة خُلقت من الرجل؛ فهو أصلها، وله أن يمنعها من التصرف إلا بإذنه، فلا تصوم إلا بإذنه، ولا تحج إلا معه. القرطبي: ٤/٥٣.\nينادي الكفار و المنافقون بتساوي الرجل مع المرأة، فكيف ترد على ذلك؟\nٱلطَّلَٰقُ مَرَّتَانِۖ\nلأن من زاد على الثنتين؛ فإمَّا متجرّئ على المحرّم، أو ليس له رغبة في إمساكها، بل قصده المضارة. السعدي: ١٠٢.\nلماذا قُصِرَ الطلاق الرجعي على المرتين فقط؟\nفَلَا جُنَاحَ عَلَيۡهِمَآ أَن يَتَرَاجَعَآ إِن ظَنَّآ أَن يُقِيمَا حُدُودَ ٱللَّهِۗ\nفي هذا دلالة على أنه ينبغي للإنسان إذا أراد أن يدخل في أمر من الأمور -خصوصًا الولايات الصغار والكبار- أن ينظر في نفسه؛ فإن رأى من نفسه قوة على ذلك ووثق بها أقدم، وإلا أحجم. السعدي: ١٠٣.\nكيف يتعامل الإنسان مع الولايات التي تعرض عليه؟"],[37,"§البقرة\nwords\nضِرَارًامُضَارَّةً.\nتَعضُلُوهُنَّتَمنَعُوهُنَّ.\nفِصَالًافِطَامًا.\ndeeds\nأرسل رسالة تبين فيها أن من تلاعب بأحكام الزواج تلاعب بأحكام الطلاق، وهذا من الاستهزاء بحدود الله.\nإذا أصبحت فقل: \"اللهم ما أصبح بي من نعمة أو بأحد من خلقك فمنك وحدك لا شريك لك؛ فلك الحمد، ولك الشكر\"، وإذا أمسيت فقل: \"اللهم ما أمسى\".\nانصح أهل زوجين متخاصمين، أو مطلقين، بتسهيل تراجعهما.\nguid\nالرجل الكريم النفس الطيب الخلق لا يعامل زوجته إلا بالمعروف؛ سواء أحبها، أو كرهها.\nالغضب والخلاف لا يجيزان الاستهزاء بالأحكام الشرعية.\nاقبل الموعظة، ولو جاءتك ممن هو أقل منك، وتأملها كثيرًا؛ فإن ذلك دليل على إيمانك بالله واليوم الآخر.\nrefl\nوَلَا تَتَّخِذُوٓاْ ءَايَٰتِ ٱللَّهِ هُزُوٗاۚ\nبأن تعرضوا عنها، وتتهاونوا في المحافظة عليها؛ فجدُّوا في الأخذ بها، والعمل بما فيها، وارعوها حق رعايتها. الألوسي: ٢/١٤٣.\nالتلاعب بأحكام الزواج يؤدي إلى التلاعب بأحكام الطلاق والاستهزاء بأحكام الشرع، وضح ذلك.\nوَلَا تَتَّخِذُوٓاْ ءَايَٰتِ ٱللَّهِ هُزُوٗاۚ\nالاستهزاء بدين الله من الكبائر، والاستهزاء هو السخرية؛ وهو حمل الأقوال والأفعال على الهزل واللعب. ابن تيمية: ١/٥٤٣.\nما حكم الاستهزاء بدين الله تعالى؟\nوَإِذَا طَلَّقۡتُمُ ٱلنِّسَآءَ فَبَلَغۡنَ أَجَلَهُنَّ فَلَا تَعۡضُلُوهُنَّ أَن يَنكِحۡنَ أَزۡوَٰجَهُنَّ إِذَا تَرَٰضَوۡاْ بَيۡنَهُم بِٱلۡمَعۡرُوفِۗ\nنزلت هذه الآية في الرجل يطلق امرأته طلقة أو طلقتين؛ فتنقضي عدتها، ثم يبدو له أن يتزوجها وأن يراجعها، وتريد المرأة ذلك؛ فيمنعها أولياؤها من ذلك، فنهى الله أن يمنعوها... وفيها دلالة على أن المرأة لا تملك أن تزوِّج نفسها، وأنه لا بد في النكاح من ولي. ابن كثير: ١/٢٦٧.\nكيف تستدل بهذه الآية على اشتراط الولي للمرأة في النكاح؟\nوَإِذَا طَلَّقۡتُمُ ٱلنِّسَآءَ فَبَلَغۡنَ أَجَلَهُنَّ فَلَا تَعۡضُلُوهُنَّ أَن يَنكِحۡنَ أَزۡوَٰجَهُنَّ إِذَا تَرَٰضَوۡاْ بَيۡنَهُم بِٱلۡمَعۡرُوفِۗ ذَٰلِكَ يُوعَظُ بِهِۦ مَن كَانَ مِنكُمۡ يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۗ ذَٰلِكُمۡ أَزۡكَىٰ لَكُمۡ وَأَطۡهَرُۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ ٢٣٢\nوالإشارة في ﴿ذَٰلِكُمۡ أَزۡكَىٰ﴾ إلى ترك العضل، وأَزكى وأَطهَرُ معناه: أطيب للنفس، وأطهر للعرض والدين؛ بسبب العلاقات التي تكون بين الأزواج، وربما لم يعلمها الولي؛ فيؤدي العضل إلى الفساد والمخالطة على ما لا ينبغي، والله تعالى يعلم من ذلك ما لا يعلم البشر. ابن عطية: ١/٣١٠.\nمتى يكون دخول طرف ثالث في قضايا الزوجية ضررًا عليهما؟\nذَٰلِكَ يُوعَظُ بِهِۦ مَن كَانَ مِنكُمۡ يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۗ\nوفيه إيذان بأن المشار إليه أمر لا يكاد يتصوره كل أحد؛ بل لا بد لتصور ذلك من مؤيد من عند الله تعالى. ﴿يُوعَظُ بِهِۦ مَن كَانَ مِنكُمۡ يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۗ﴾: خصّه بالذكر لأنه المسارع إلى الامتثال؛ إجلالًا لله تعالى، وخوفًا من عقابه. الألوسي: ٢/١٤٥.\nلماذا خص المؤمن بالله واليوم الآخر بهذه الموعظة؟\nوَٱلۡوَٰلِدَٰتُ يُرۡضِعۡنَ أَوۡلَٰدَهُنَّ حَوۡلَيۡنِ كَامِلَيۡنِۖ لِمَنۡ أَرَادَ أَن يُتِمَّ ٱلرَّضَاعَةَۚ\nيدل على أن هذا تمام الرضاعة، وما بعد ذلك فهو غذاء من الأغذية. ابن تيمية: ١/٥٥٣.\nما حد إتمام الرضاعة؟\nلَا تُضَآرَّ وَٰلِدَةُۢ بِوَلَدِهَا وَلَا مَوۡلُودٞ لَّهُۥ بِوَلَدِهِۦۚ وَعَلَى ٱلۡوَارِثِ مِثۡلُ ذَٰلِكَۗ\nلا تأبى الأم أن ترضعه إضرارًا بأبيه، أو تطلب أكثر من أجر مثلها، ولا يحل للأب أن يمنع الأم من ذلك؛ مع رغبتها في الإرضاع. القرطبي: ٤/١١٦.\nكيف تكون مضارة كل من الأم أو الأب بالآخر في أمر الرضاع؟"],[38,"§البقرة\nwords\nعَرَّضتُملَمَّحتُم.\nأَكنَنتُمأَضمَرتُم.\nعُقدَةَ النِّكَاحِعَقدَ النِّكَاحِ.\nتَفرِضُواتُحَدِّدُوا.\nفَرِيضَةًمَهرًا.\nوَمَتِّعُوهُنَّأَعطُوهُنَّ شَيئًا مِنَ المَالِ؛ جَبرًا لَهُنَّ.\ndeeds\nدرب نفسك هذا اليوم في خلواتك ومخالطتك أن لا تفكر إلا في خير.\nتب إلى الله تعالى من ذنب من ذنوب السر.\nتذكر أحدًا أخطأ عليك، واعف عنه محتسبًا على ربك أن يعوّضك التقوى في قلبك.\nguid\nالاستسلام لخواطر الشر بداية المعصية فادفعها عنك قدر الإمكان.\nاجعل معاملتك للناس قائمة على الفضل والإحسان إليهم.\nوصى الإسلام بحفظ الجميل والفضل؛ فذلك أدعى للعفو عن الناس.\nrefl\nوَٱلَّذِينَ يُتَوَفَّوۡنَ مِنكُمۡ وَيَذَرُونَ أَزۡوَٰجٗا يَتَرَبَّصۡنَ بِأَنفُسِهِنَّ أَرۡبَعَةَ أَشۡهُرٖ وَعَشۡرٗاۖ\nالإحداد: ترك المرأة الزينة كلها من: اللباس، والطيب، والحلي، والكحل، والخضاب بالحناء؛ ما دامت في عدتها؛ لأن الزينة داعية إلى الأزواج، فنهيت عن ذلك قطعًا للذرائع، وحماية لحرمات الله تعالى أن تنتهك. القرطبي: ٤/١٣٣.\nبيّن شيئًا من حكمة الشرع في إحداد المرأة.\nوَٱلَّذِينَ يُتَوَفَّوۡنَ مِنكُمۡ وَيَذَرُونَ أَزۡوَٰجٗا يَتَرَبَّصۡنَ بِأَنفُسِهِنَّ أَرۡبَعَةَ أَشۡهُرٖ وَعَشۡرٗاۖ\nقال سعيد بن المسيب: \"الحكمة في هذه المدة أن فيها ينفخ الروح في الولد\"، ويقال: إن الولد يرتكض؛ أي: يتحرك في البطن\". البغوي: ١/٢٣٨.\nبيّن حكمة تحديد مدة الحداد على الزوج بأربعة أشهر وعشرٍ.\nفَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا فَعَلۡنَ فِيٓ أَنفُسِهِنَّ بِٱلۡمَعۡرُوفِۗ\nدليل على أن الولي ينظر على المرأة، ويمنعها مما لا يجوز فعله، ويجبرها على ما يجب، وأنه مخاطب بذلك، واجب عليه. السعدي: ١٠٥.\nما واجب الولي مع موليته؟\nلَّا جُنَاحَ عَلَيۡكُمۡ إِن طَلَّقۡتُمُ ٱلنِّسَآءَ مَا لَمۡ تَمَسُّوهُنَّ أَوۡ تَفۡرِضُواْ لَهُنَّ فَرِيضَةٗۚ وَمَتِّعُوهُنَّ عَلَى ٱلۡمُوسِعِ قَدَرُهُۥ وَعَلَى ٱلۡمُقۡتِرِ قَدَرُهُۥ مَتَٰعَۢا بِٱلۡمَعۡرُوفِۖ\nأباح -تبارك وتعالى- طلاق المرأة بعد العقد عليها وقبل الدخول بها... وإن كان في هذا انكسار لقلبها، ولهذا أمر تعالى بإمتاعها؛ وهو تعويضها عما فاتها بشيء تُعطاه من زوجها بحسب حاله؛ على الموسع قدره، وعلى المقتر قدره. ابن كثير: ١/٢٧٢.\nلماذا أمر تعالى بتمتيع المرأة المطلقة التي لم يُدخَل بها؟\nوَأَن تَعۡفُوٓاْ أَقۡرَبُ لِلتَّقۡوَىٰۚ وَلَا تَنسَوُاْ ٱلۡفَضۡلَ بَيۡنَكُمۡۚ إِنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٌ ٢٣٧\nمعاملة الناس فيما بينهم على درجتين: إما عدل وإنصاف واجب؛ وهو: أخذ الواجب وإعطاء الواجب، وإما فضل وإحسان؛ وهو: إعطاء ما ليس بواجب، والتسامح في الحقوق، والغض مما في النفس؛ فلا ينبغي للإنسان أن ينسى هذه الدرجة، ولو في بعض الأوقات. السعدي: ١٠٥.\nنهينا عن نسيان الفضل بيننا، فما المقصود به؟\nوَلَا تَنسَوُاْ ٱلۡفَضۡلَ بَيۡنَكُمۡۚ إِنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٌ ٢٣٧\nوالفضل بمعنى الإحسان؛ أي: لا تنسوا الإحسان الكائن بينكم من قبل، وليكن منكم على ذكر؛ حتى يرغب كل في العفو مقابلة لإحسان صاحبه عليه. الألوسي: ٣/١٥٥.\nلماذا طلب من الزوجين تذكر الفضل بينهما؟\nوَلَا تَنسَوُاْ ٱلۡفَضۡلَ بَيۡنَكُمۡۚ إِنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٌ ٢٣٧\nمن حق الزوج الذي له فضل الرجولة أن يكون هو العافي، وأن لا يؤاخذ النساء بالعفو، ولذلك لم يأت في الخطاب أمر لهن ولا تحريض، فمن أقبح ما يكون حمل الرجل على المرأة في استرجاع ما آتاها... فينبغي أن لا تنسوا ذلك الفضل. البقاعي: ١/٤٤٨.\nما دلالة قوله تعالى: ﴿وَلَا تَنسَوُاْ ٱلۡفَضۡلَ بَيۡنَكُمۡۚ﴾؟"],[39,"§البقرة ، الأنعام\nwords\nوَالصَّلاَةِ الوُسطَىصَلاَةِ العَصرِ.\nخَوضِهِمحَدِيثِهِمُ البَاطِلِ.\nقَانِتِينَمُطِيعِينَ خَاشِعِينَ.\nفَرِجَالًامَاشِينَ.\ndeeds\nاذهب إلى صلاة العصر مبكرًا.\nتأمل صور من يسجدون للأضرحة والأصنام، ويذبحون لها، ويطوفون حولها، ثم اشكر الله تعالى على نعمة الهداية.\nأقرض ربك قرضًا حسنًا؛ فستحتاجه كثيرًا وقت الوفاء.\nguid\nفي ذكر الصلاة ضمن آيات الطلاق دليل على أن محافظة الأسرة على الصلاة من أهم أسباب استقرارها وسعادتها.\nحافظ على جميع الصلوات في وقتها؛ وخصوصًا صلاة العصر.\nالأسباب لا ترد القضاء؛ فلا بد من التسليم للقضاء مع اتخاذ الأسباب.\nrefl\nحَٰفِظُواْ عَلَى ٱلصَّلَوَٰتِ وَٱلصَّلَوٰةِ ٱلۡوُسۡطَىٰ وَقُومُواْ لِلَّهِ قَٰنِتِينَ ٢٣٨\nإن الله -سبحانه وتعالى- يعطي الدنيا على نية الآخرة، وأبى أن يعطي الآخرة على نية الدنيا؛ خلل حال المرء في دنياه ومعاده إنَّما هو عن خلل حال دينه، وملاك دينه وأساسه إيمانه وصلاته؛ فمن حافظ على الصلوات أصلح الله حال دنياه وأخراه. البقاعي: ١/٤٥٠.\nذكر آية الصلاة بين آيات الطلاق يوحي بعلاقة بين صلاح الأسرة والصلاة، فما هذه العلاقة؟\nحَٰفِظُواْ عَلَى ٱلصَّلَوَٰتِ وَٱلصَّلَوٰةِ ٱلۡوُسۡطَىٰ وَقُومُواْ لِلَّهِ قَٰنِتِينَ ٢٣٨\nقال بعضهم: هي إحدى الصلوات الخمس لا بعينها؛ أبهمها الله تعالى تحريضًا للعباد على المحافظة على أداء جميعها؛ كما أخفى ليلة القدر في شهر رمضان، وساعة إجابة الدعوة في يوم الجمعة، وأخفى اسمه الأعظم في الأسماء؛ ليحافظوا على جميعها. البغوي: ١/٢٥٢.\nأحيانًا يرد فضل لعبادة ولا تحدد العبادة بعينها، فما الحكمة من ذلك؟\nفَإِنۡ خِفۡتُمۡ فَرِجَالًا أَوۡ رُكۡبَانٗاۖ\nويلزم على ذلك أن يكونوا مستقبلي القبلة وغير مستقبليها، وفي هذا زيادة التأكيد على المحافظة على وقتها؛ حيث أمر بذلك ولو مع الإخلال بكثير من الأركان والشروط، وأنه لا يجوز تأخيرها عن وقتها ولو في هذه الحالة الشديدة، فصلاتها على تلك الصورة أحسن وأفضل، بل أوجب من صلاتها مطمئنًا خارج الوقت. السعدي: ١٠٦.\nعلى ماذا يدل الأمر بالصلاة رجالًا أو ركبانًا في حال الخوف؟\nأَلَمۡ تَرَ إِلَى ٱلَّذِينَ خَرَجُواْ مِن دِيَٰرِهِمۡ وَهُمۡ أُلُوفٌ حَذَرَ ٱلۡمَوۡتِ فَقَالَ لَهُمُ ٱللَّهُ مُوتُواْ ثُمَّ أَحۡيَٰهُمۡۚ\nالمقصود من هذه الآية الكريمة: تشجيع المؤمنين على القتال بإعلامهم بأن الفرار من الموت لا ينجي؛ فإذا علم الإنسان أن فراره من الموت أو القتل لا ينجيه هانت عليه مبارزة الأقران والتقدم في الميدان. الشنقيطي: ١/١٥٢.\nما مقصود الآية الكريمة؟\nأَلَمۡ تَرَ إِلَى ٱلَّذِينَ خَرَجُواْ مِن دِيَٰرِهِمۡ وَهُمۡ أُلُوفٌ حَذَرَ ٱلۡمَوۡتِ فَقَالَ لَهُمُ ٱللَّهُ مُوتُواْ ثُمَّ أَحۡيَٰهُمۡۚ\nجعل الله تعالى هذه القصة لما فيها من تشجيع المسلمين على الجهاد، والتعرض للشهادة، والحث على التوكل، والاستسلام للقضاء؛ تمهيدًا لقوله تعالى: ﴿وَقَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ﴾. الألوسي: ٢/١٦٢.\nلماذا أورد الله تعالى هذه القصة قبل الأمر بالقتال؟\nمَّن ذَا ٱلَّذِي يُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنٗا فَيُضَٰعِفَهُۥ لَهُۥٓ أَضۡعَافٗا كَثِيرَةٗۚ وَٱللَّهُ يَقۡبِضُ وَيَبۡصُۜطُ وَإِلَيۡهِ تُرۡجَعُونَ ٢٤٥\n(قرضًاحسنًا) يعني: محتسبًا طيبةً بها نفسه، وقال ابن المبارك: \"من مال حلال\"، وقيل: لا يمُنّ، ولا يؤذي. البغوي: ١/٢٥٢.\nكيف يكون القرض قرضًا حسنًا؟\nمَّن ذَا ٱلَّذِي يُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنٗا\nاستفهام يراد به الطلب والحض على الإنفاق، وذكر لفظ القرض تقريبًا للأفهام؛ لأن المنفق ينتظر الثواب كما ينتظر المسلف ردّ ما أسلف. ابن جزي: ١/١١٨.\nما وجه التعبير بـ (القرض) في الحث على الإنفاق؟"],[40,"§البقرة\nwords\nهَل عَسَيتُمهَلِ الأَمرُ كَمَا أَتَوَقَّعُهُ؟\nبَسطَةًسَعَةً.\nالتَّابُوتُالصُّندُوقُ الَّذِي فِيهِ التَّورَاةُ.\ndeeds\nلا تتمنَّ لقاء العدو، وإن لقيته فاصبر واثبت.\nألحّ على الله بالدعاء أن يجعلك ممن اصطفاه ربنا سبحانه في الدنيا والآخرة.\nأكثر اليوم من دعاء: \"رب زدني علمًا\".\nguid\nالثبات عند الابتلاء من صفات المؤمنين.\nقد يصطفي الله من عباده علماءً ودعاةً وعُبَّادًا، وفقراءً وتجَّارًا وملوكًا؛ فلا تكن حاسدًا لأحد منهم.\nاحذر التطلع إلى المناصب إرضاءً لنفسك؛ فإنها فتنة، وإن ابتليت بها فاستعن بالله عليها، واقترب من الله أكثر.\nrefl\nقَالُواْ وَمَا لَنَآ أَلَّا نُقَٰتِلَ فِي سَبِيلِ ٱللَّهِ وَقَدۡ أُخۡرِجۡنَا مِن دِيَٰرِنَا وَأَبۡنَآئِنَاۖ فَلَمَّا كُتِبَ عَلَيۡهِمُ ٱلۡقِتَالُ تَوَلَّوۡاْ إِلَّا قَلِيلٗا مِّنۡهُمۡۚ وَٱللَّهُ عَلِيمُۢ بِٱلظَّٰلِمِينَ ٢٤٦\nوموضع العبرة هو التحذير من الوقوع في مثل حالهم بعد الشروع في القتال، أو بعد كتبه عليهم. ابن عاشور: ٢/٤٨٤.\nما موضع العبرة من هذه الآية؟\nقَالُواْ وَمَا لَنَآ أَلَّا نُقَٰتِلَ فِي سَبِيلِ ٱللَّهِ وَقَدۡ أُخۡرِجۡنَا مِن دِيَٰرِنَا وَأَبۡنَآئِنَاۖ فَلَمَّا كُتِبَ عَلَيۡهِمُ ٱلۡقِتَالُ تَوَلَّوۡاْ إِلَّا قَلِيلٗا مِّنۡهُمۡۚ وَٱللَّهُ عَلِيمُۢ بِٱلظَّٰلِمِينَ ٢٤٦\nفيه إشعار لهذه الأمة بأن لا تطلب الحرب ابتداءً، وإنَّما تدافع عن منعها من إقامة دينها؛ كما قال -سبحانه وتعالى-: ﴿أُذِنَ لِلَّذِينَ يُقَٰتَلُونَ بِأَنَّهُمۡ ظُلِمُواْ﴾ [الحج: ٣٩]، فحق المؤمن أن يأبى الحرب ولا يطلبه؛ فإنه إن طلبه فأوتيه عجز كما عجز هؤلاء حين تولَّوا إلا قليلًا. البقاعي: ١/٤٧٠.\nالأصل أن نبدأ بالدعوة، فمتى إذًا يشرع الجهاد؟\nقَالُواْ وَمَا لَنَآ أَلَّا نُقَٰتِلَ فِي سَبِيلِ ٱللَّهِ وَقَدۡ أُخۡرِجۡنَا مِن دِيَٰرِنَا وَأَبۡنَآئِنَاۖ\nفأنبأ -سبحانه وتعالى- أنهم أسندوا ذلك إلى غضب الأنفس على الإخراج، وإنَّما يقاتل في سبيل الله من قاتل لتكون كلمة الله هي العليا. البقاعي: ١/٤٧٢.\nمن أسباب خذلان الله سبحانه للمقاتل أن تكون نيته ليست لله سبحانه، وضح ذلك.\nفَلَمَّا كُتِبَ عَلَيۡهِمُ ٱلۡقِتَالُ تَوَلَّوۡاْ إِلَّا قَلِيلٗا مِّنۡهُمۡۚ وَٱللَّهُ عَلِيمُۢ بِٱلظَّٰلِمِينَ ٢٤٦\nلما فرض عليهم القتال، ورأوا الحقيقة، ورجعت أفكارهم إلى مباشرة الحرب؛ (تولوا) أي: اضطربت نياتهم، وفترت عزائمهم. وهذا شأن الأمم المتنعمة، المائلة إلى الدعة؛ تتمنى الحرب أوقات الأنفة، فإذا حضرت الحرب كَعّت وانقادت لطبعها. ابن عطية: ١/٣٣١.\nما خطورة تربية المجتمع على التنعم؟\nإِنَّ ٱللَّهَ ٱصۡطَفَىٰهُ عَلَيۡكُمۡ وَزَادَهُۥ بَسۡطَةٗ فِي ٱلۡعِلۡمِ وَٱلۡجِسۡمِۖ\nأي: أتمّ علمًا وقامةً منكم؛ ومن هاهنا ينبغي أن يكون الملك ذا علم، وشكل حسن، وقوة شديدة في بدنه ونفسه. ابن كثير: ١/٢٨٥.\nفي هذه الآية بعض الصفات التي ينبغي أن يتصف بها الملك، فما هي؟\nإِنَّ ٱللَّهَ ٱصۡطَفَىٰهُ عَلَيۡكُمۡ وَزَادَهُۥ بَسۡطَةٗ فِي ٱلۡعِلۡمِ وَٱلۡجِسۡمِۖ\nفي تقديم البسطة في العلم على البسطة في الجسم إيماء إلى أن الفضائل النفسانية أعلى وأشرف من الفضائل الجسمانية، بل يكاد لا يكون بينهما نسبة. الألوسي: ٢/١٦٧.\nلماذا قدم البسطة في العلم على البسطة في الجسم؟\nإِنَّ ٱللَّهَ ٱصۡطَفَىٰهُ عَلَيۡكُمۡ وَزَادَهُۥ بَسۡطَةٗ فِي ٱلۡعِلۡمِ وَٱلۡجِسۡمِۖ\nلا تستبعدوا تملكه عليكم لفقره وانحطاط نسبه عنكم؛ أمَّا أولًا: فلأن ملاك الأمر هو اصطفاء الله تعالى، وقد اصطفاه واختاره، وهو سبحانه أعلم بالمصالح لكم، وأمَّا ثانيا: فلأن العمدة وفور العلم ليتمكن به من معرفة الأمور السياسية، وجسامة البدن ليكون أعظم خطرًا في القلوب، وأقوى على كفاح الأعداء ومكابدة الحروب. الألوسي: ٢/١٦٧.\nما الفرق بين المقاييس الربانية والمقاييس البشرية في اصطفاء البشر؟"],[41,"§البقرة\nwords\nيَظُنُّونَيُوقِنُونَ.\ndeeds\nاقرأ قصة طالوت من أحد كتب التفسير، ثم استخـرج منها ثـلاث فوائد.\nأكثر من الدعاء بالثبات، ثم درب نفسك اليوم بترك محبوب مباح؛ كأن تصوم يومًا نافلةً حتى لا تنهزم عند الابتلاء.\nادع بهذا الدعاء لنفسك، وانصح به أهل الابتلاء.\nguid\nالذي يفرغ الصبر، ويثبت الأقدام، وينصر على أهل الكفر هو الله سبحانه.\nالدعاء عند الشدائد، وإظهار الافتقار والحاجة لله من أهم أسباب النصر.\nطول التفكير في الآخرة يورث الثبات واليقين بالله وبنصره.\nrefl\nقَالَ ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُواْ ٱللَّهِ كَم مِّن فِئَةٖ قَلِيلَةٍ غَلَبَتۡ فِئَةٗ كَثِيرَةَۢ بِإِذۡنِ ٱللَّهِۗ وَٱللَّهُ مَعَ ٱلصَّٰبِرِينَ ٢٤٩\nالآية تحريض على القتال واستشعار للصبر، واقتداء بمن صدق ربه، قلت: هكذا يجب علينا نحن أن نفعل، لكن الأعمال القبيحة والنيات الفاسدة منعت من ذلك حتى ينكسر العدد الكثير منا قدام اليسير من العدو؛ كما شاهدناه غير مرة؛ وذلك بما كسبت أيدينا؛ قال أبو الدرداء: \"إنَّما تقاتلون بأعمالكم\". القرطبي: ٤/٢٤٥.\nبينت الآية سببًا من أسباب النصر على الأعداء فما هو ؟\nوَٱللَّهُ مَعَ ٱلصَّٰبِرِينَ ٢٤٩\nفأعظم جالب لمعونة الله: صبر العبد لله. السعدي: ١٠٨.\nما أعظم جالب لمعية الله للعبد؟\nوَلَمَّا بَرَزُواْ لِجَالُوتَ وَجُنُودِهِۦ قَالُواْ رَبَّنَآ أَفۡرِغۡ عَلَيۡنَا صَبۡرٗا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ ٢٥٠\nفيه حسن الترتيب؛ حيث طلبوا أولًا: إفراغ الصبر على قلوبهم عند اللقاء، وثانيًا: ثبات القدم والقوة على مقاومة العدو؛ حيث إن الصبر قد يحصل لمن لا مقاومة له، وثالثًا: العمدة والمقصود من المحاربة؛ وهو النصرة على الخصم. الألوسي: ٢/١٧٢.\nأفضل الدعاء أشمله لحاجة العبد، وضح ذلك من الآية.\nفَهَزَمُوهُم بِإِذۡنِ ٱللَّهِ\nعلى العاقل المعتقد جهله بالعواقب وشمول قدرة ربه أن لا يثق بنفسه في شيء من الأشياء، ولا يزال يصفها بالعجز وإن ادعت خلاف ذلك، ويتبرأ من حوله وقوته إلى حول مولاه وقوته؛ ولا ينفك يسأله العفو والعافية. البقاعي: ١/٤٨٣.\nما الثقة المحمودة وما الثقة المذمومة؟\nوَقَتَلَ دَاوُۥدُ جَالُوتَ وَءَاتَىٰهُ ٱللَّهُ ٱلۡمُلۡكَ وَٱلۡحِكۡمَةَ وَعَلَّمَهُۥ مِمَّا يَشَآءُۗ\nتنبيه على فضيلة الملك، وأنه لولاه ما استتب أمر العالم؛ ولهذا قيل: الدين والمُلك توأمان؛ ففي ارتفاع أحدهما ارتفاع الآخر؛ لأن الدين أس والملك حارس، وما لا أس له فمهدوم، وما لا حارس له فضائع. الألوسي: ٢/١٧٤.\nبيّن أهمية الملك من خلال الآية.\nوَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضٖ لَّفَسَدَتِ ٱلۡأَرۡضُ\nأخبر الله تعالى في هذه الآية أنه لولا دفعه بالمؤمنين في صدور الكفرة على مر الدهر ﴿لَّفَسَدَتِ ٱلۡأَرۡضُ﴾؛ لأن الكفر كان يطبقها ويتمادى في جميع أقطارها، ولكنه تعالى لا يخلي الزمان من قائمٍ بحق وداعٍ إلى الله ومقاتلٍ عليه، إلى أن جعل ذلك في أمة محمد -صلى الله عليه وسلم- إلى قيام الساعة، له الحمد كثيرًا. ابن عطية: ١/٣٣٧.\nلماذا جعل الله المدافعة بين المؤمنين والكفار دائمة إلى يوم القيامة؟\nوَلَٰكِنَّ ٱللَّهَ ذُو فَضۡلٍ عَلَى ٱلۡعَٰلَمِينَ ٢٥١\nأولًا بالإيجاد، وثانيًا بالدفاع؛ فهو يكف من ظلم الظلمة؛ إما بعضهم ببعض، أو بالصالحين -وقليل ما هم-، ويسبغ عليهم غير ذلك من أثواب نعمه ظاهرة وباطنة. البقاعي: ١/٤٨١.\nبيّن بعضًا من فضل الله على العالمين."],[42,"§البقرة\nwords\nخُلَّةٌصَدَاقَةٌ.\nالقَيُّومُالقَائِمُ عَلَى كُلِّ شَيءٍ.\nسِنَةٌنُعَاسٌ.\nكُرسِيُّهُمَوضِعُ قَدَمَيِ الرَّبِّ سُبحَانَهُ.\nيَؤُودُهُيُثقِلُهُ.\ndeeds\nلتكن لك هذا اليوم صدقة -ولو قليلة- تحاج لك عند الله في يوم.\nاقرأ آية الكرسي بعد الصلوات المفروضة؛ فإنه لا يكون بينك وبين الجنة إلا أن تموت.\nاقرأ آية الكرسي في الصباح والمساء وعند النوم يحفظك الله بها من الشيطان.\nguid\nمن أسباب الاقتتال: الاختلاف الذي منبعه الهوى أو الجهل.\nلا ينفع العبد يوم القيامة إلا عمله الصالح، ومن أعظمه الصدقة.\nتذكرك الدائم أن الله يراقبك في السر والعلن، ويعلم ما تخفي وما تعلن يساعدك على التقليل من المعاصي.\nrefl\nتِلۡكَ ٱلرُّسُلُ فَضَّلۡنَا بَعۡضَهُمۡ عَلَىٰ بَعۡضٖۘ مِّنۡهُم مَّن كَلَّمَ ٱللَّهُۖ وَرَفَعَ بَعۡضَهُمۡ دَرَجَٰتٖۚ\nومعلوم أن المرسلين يتفاضلون؛ تارةً في الكتب المنزلة عليهم، وتارةً في الآيات والمعجزات الدالة على صدقهم، وتارةً في الشرائع وما جاءوا به من العلم والعمل، وتارةً في أممهم. ابن تيمية: ١/٥٧٨ - ٥٧٩.\nبيّن شيئًا من أوجه تفاضل المرسلين -عليهم الصلاة والسلام-.\nوَٱلۡكَٰفِرُونَ هُمُ ٱلظَّٰلِمُونَ ٢٥٤\nقال عطاء بن دينار: \"والحمد لله الذي قال: ﴿وَٱلۡكَٰفِرُونَ هُمُ ٱلظَّٰلِمُونَ﴾ ولم يقل: والظالمون هم الكافرون\". القرطبي: ٤/٢٦٢.\nبيّن كيف تدبر عطاء بن دينار هذه الآية الكريمة\nٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُۚ لَا تَأۡخُذُهُۥ سِنَةٞ وَلَا نَوۡمٞۚ\nنفى الله تعالى عن نفسه النوم؛ لأنه آفة، وهو منزه عن الآفات. البغوي: ١/٢٦٩.\nلم نفى الله تعالى عن نفسه أقل النوم؟\nٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُۚ لَا تَأۡخُذُهُۥ سِنَةٞ وَلَا نَوۡمٞۚ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ مَن ذَا ٱلَّذِي يَشۡفَعُ عِندَهُۥٓ إِلَّا بِإِذۡنِهِۦۚ يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۖ وَلَا يُحِيطُونَ بِشَيۡءٖ مِّنۡ عِلۡمِهِۦٓ إِلَّا بِمَا شَآءَۚ وَسِعَ كُرۡسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۖ وَلَا ئَودُهُۥ حِفۡظُهُمَاۚ وَهُوَ ٱلۡعَلِيُّ ٱلۡعَظِيمُ ٢٥٥\nهذه الآية الكريمة أعظم آيات القرآن، وأفضلها وأجلها؛ وذلك لما اشتملت عليه من الأمور العظيمة والصفات الكريمة؛ فلهذا كثرت الأحاديث في الترغيب في قراءتها، وجعلها وردًا للإنسان في أوقاته: صباحًا، ومساءً، وعند نومه، وأدبار الصلوات المكتوبات. السعدي: ١١٠.\nلماذا شرعت قراءة آية الكرسي في أوقات مختلفة من الليل والنهار؟ ولماذا كانت أعظم آية في كتاب الله؟\nمَن ذَا ٱلَّذِي يَشۡفَعُ عِندَهُۥٓ إِلَّا بِإِذۡنِهِۦۚ\nوهذا من عظمته وجلاله وكبريائه -عز وجل-؛ أنه لا يتجاسر أحدٌ على أن يشفع لأحد عنده إلا بإذنه له في الشفاعة. ابن كثير: ١/٢٩٢.\nعلى ماذا يدل اشتراط إذنه -سبحانه وتعالى- لمن أراد الشفاعة؟\nلَآ إِكۡرَاهَ فِي ٱلدِّينِۖ\nلعدم الحاجة إلى الإكراه عليه؛ لأن الإكراه لا يكون إلا على أمر خَفيَّة أعلامه، غامضة آثاره، أو أمر في غاية الكراهة للنفوس، وأما هذا الدين القويم والصراط المستقيم فقد تبينت أعلامه للعقول، وظهرت طرقه، وتبين أمره، وعرف الرشد من الغي، فالموفق إذا نظر أدنى نظر إليه آثره واختاره، وأمَّا من كان سيئ القصد، فاسد الإرادة، خبيث النفس، يرى الحق فيختار عليه الباطل، ويبصر الحسن فيميل إلى القبيح؛ فهذا ليس لله حاجة في إكراهه على الدين؛ لعدم النتيجة والفائدة فيه، والمكره ليس إيمانه صحيحًا. السعدي: ١١١.\nلماذا لم تكن هناك حاجة لإكراه الناس على الدين؟\nفَمَن يَكۡفُرۡ بِٱلطَّٰغُوتِ وَيُؤۡمِنۢ بِٱللَّهِ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰ لَا ٱنفِصَامَ لَهَاۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ ٢٥٦\nولما كان الكفر بالطاغوت والإيمان بالله مما ينطق به اللسان، ويعتقده القلب، حسن في الصفات: (سميع) من أجل النطق، (عليم) من أجل المعتقد. القرطبي: ٤/٢٨٥.\nما سر ختم الآية الكريمة بصفتي: (السميع)، و(العليم) لله -عز وجل-؟"],[43,"§البقرة\nwords\nفَبُهِتَتَحَيَّرَ، وَانقَطَعَت حُجَّتُهُ.\nعُرُوشِهَاسُقُوفِهَا.\nيَتَسَنَّهيَتَغَيَّر.\nنُنشِزُهَانَرفَعُهَا، وَنَصِلُ بَعضَهَا بِبَعضٍ.\ndeeds\nحدد ثلاثة من الأعمال التي يحبها الله، واعمل بها، ثم قل: \"اللهم تولني فيمن توليت\".\nاستخرج ثلاثة آداب للحوار والمناظرة من قصة إبراهيم -عليه السلام-.\nقل: \"اللهم يا معلم إبراهيم علمني، ويا مفهم سليمان فهمني\".\nguid\nالإيمان والعمل الصالح يحققان لك ولاية الله سبحانه، والفسق والغفلة عن ذكر الله تجلبان ولاية الشيطان والعياذ بالله.\nمن أعظم نعم الله على أوليائه أنهم يرون بنور الله.\nالنعم الدنيوية إذا لم يصاحبها إيمان بالله فهي وبال على صاحبها، وزيادة في سيئاته.\nrefl\nٱللَّهُ وَلِيُّ ٱلَّذِينَ ءَامَنُواْ يُخۡرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۖ\nناصرهم ومعينهم، وقيل: محبهم، وقيل: متولي أمورهم لا يكلهم إلى غيره، وقال الحسن: \"وليُّ هدايتهم\". البغوي: ١/٢٧٣.\nكيف تكون ولاية الله تعالى للمؤمنين؟\nٱللَّهُ وَلِيُّ ٱلَّذِينَ ءَامَنُواْ يُخۡرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۖ وَٱلَّذِينَ كَفَرُوٓاْ أَوۡلِيَآؤُهُمُ ٱلطَّٰغُوتُ يُخۡرِجُونَهُم مِّنَ ٱلنُّورِ إِلَى ٱلظُّلُمَٰتِۗ\nوحَّد تعالى لفظ النور، وجمع الظلمات؛ لأن الحق واحد، والكفر أجناس كثيرة وكلها باطلة. ابن كثير: ١/٢٩٥.\nلماذا وُحِّدَ لفظ (النور)، وجمع لفظ (الظلمات) في الآية؟\nٱللَّهُ وَلِيُّ ٱلَّذِينَ ءَامَنُواْ يُخۡرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۖ\nفأخرجهم من ظلمات الكفر والمعاصي والجهل إلى نور الإيمان والطاعة والعلم، وكان جزاؤهم على هذا أن سلَّمهم من ظلمات القبر والحشر والقيامة إلى النعيم المقيم والراحة والفسحة والسرور. السعدي: ١١١.\nما الظلمات التي يخرج منها المؤمن عند إيمانه؟ وما النور الذي يلاقيه؟\nٱللَّهُ وَلِيُّ ٱلَّذِينَ ءَامَنُواْ يُخۡرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۖ وَٱلَّذِينَ كَفَرُوٓاْ أَوۡلِيَآؤُهُمُ ٱلطَّٰغُوتُ يُخۡرِجُونَهُم مِّنَ ٱلنُّورِ إِلَى ٱلظُّلُمَٰتِۗ\nسُمي الكفر ظلمة لالتباس طريقه، وسُمي الإسلام نورًا لوضوح طريقه. البغوي: ١/٢٧٣.\nلم سمى الله تعالى الكفر ظلمة، والإسلام نورًا؟\nٱللَّهُ وَلِيُّ ٱلَّذِينَ ءَامَنُواْ يُخۡرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۖ وَٱلَّذِينَ كَفَرُوٓاْ أَوۡلِيَآؤُهُمُ ٱلطَّٰغُوتُ يُخۡرِجُونَهُم مِّنَ ٱلنُّورِ إِلَى ٱلظُّلُمَٰتِۗ\nفالله يزيد الذين اهتدوا هدى؛ لأن اتباعهم الإسلام تيسير لطرق اليقين؛ فهم يزدادون توغلًا فيها يومًا فيومًا. وبعكسهم الذين اختاروا الكفر على الإسلام؛ فإن اختيارهم ذلك دل على ختم ضرب على عقولهم، فلم يهتدوا، فهم يزدادون في الضلال يومًا فيومًا. ابن عاشور: ٣/٣٠.\nالإنسان لا بد أن يتقدم: إما في الخير، وإما في الشر، وضح ذلك من الآية.\nأَلَمۡ تَرَ إِلَى ٱلَّذِي حَآجَّ إِبۡرَٰهِۧمَ فِي رَبِّهِۦٓ\nقال إلْكِيا: وفي الآية دليل على جواز المحاجة في الدين. الألوسي: ٣/١٩.\nهل يجوز المحاجة في الدين؟\nرَبِّيَ ٱلَّذِي يُحۡيِۦ وَيُمِيتُ\nأي: هو المنفرد بأنواع التصرف، وخص منه الإحياء والإماتة لكونهما أعظم أنواع التدابير. السعدي: ١١١.\nلماذا ذكر إبراهيم الإحياء والإماتة دون غيرهما؟"],[44,"§البقرة\nwords\nفَصُرهُنَّ إِلَيكَاضمُمهُنَّ إِلَيكَ، وَقَطِّعهُنَّ.\nصَفوَانٍحَجَرٍ أَملَسَ.\nوَابِلٌمَطَرٌ غَزِيرٌ.\nصَلدًاأَجرَدَ لاَ تُرَابَ عَلَيهِ.\ndeeds\nتصدق اليوم بصدقة لا يطلع عليها أحد من البشر.\nابحث في كتب التفسير عن سر ختم آية الحث على الصدقة بصفتي: الواسع العليم لله -عز وجل-.\nتواصل اليوم مع محتاج، وقل له قولًا جميلًا، وادع له، وتبسم في وجهه؛ وتصدق عليه حتى يتضاعف أجرك.\nguid\nإذا كان الإنفاق بحب وتواضع ولا يتبعه مَنٌّ ولا أذىً؛ فإنه يدفع عن صاحبه الخوف والحزن في الدنيا ويوم القيامة.\nالكلمة الطيبة والعفو عن الناس أفضل من صدقة فيها أذى ومنّة.\nالرياء دليل على ضعف إيمان صاحبه بالله واليوم الآخر.\nrefl\nقَالَ فَخُذۡ أَرۡبَعَةٗ مِّنَ ٱلطَّيۡرِ فَصُرۡهُنَّ إِلَيۡكَ ثُمَّ ٱجۡعَلۡ عَلَىٰ كُلِّ جَبَلٖ مِّنۡهُنَّ جُزۡءٗا ثُمَّ ٱدۡعُهُنَّ يَأۡتِينَكَ سَعۡيٗاۚ وَٱعۡلَمۡ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ ٢٦٠\nوالظاهر أن حكمة التعدد والاختلاف زيادة في تحقق أن الإحياء لم يكن أهون في بعض الأنواع دون بعض. ابن عاشور: ٣/٣٩.\nلماذا جعلت الطيور المذبوحة أكثر من واحد، وربما أكثر من نوع؟\nوَٱللَّهُ يُضَٰعِفُ لِمَن يَشَآءُۚ\nبحسب حال المنفق وإخلاصه وصدقه، وبحسب حال النفقة وحِلِّها ونفعها ووقوعها موقعها. السعدي: ١١٣.\nما الأسباب التي تجعل أجر الحسنة يتضاعف؟\nٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ فِي سَبِيلِ ٱللَّهِ ثُمَّ لَا يُتۡبِعُونَ مَآ أَنفَقُواْ مَنّٗا وَلَآ أَذٗى لَّهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ٢٦٢\nوإنَّما كان المن بالصدقة مفسدًا لها محرمًا؛ لأن المنة لله تعالى وحده، والإحسان كله لله؛ فالعبد لا يمن بنعمة الله وإحسانه وفضله، وهو ليس له، وأيضًا فإن المانَّ مستعبد لمن يمن عليه، والذل والاستعباد لا ينبغي إلا لله. السعدي: ١١٣.\nلماذا كان المَنُّ مفسدًا للصدقة؟\nقَوۡلٞ مَّعۡرُوفٞ وَمَغۡفِرَةٌ خَيۡرٞ مِّن صَدَقَةٖ يَتۡبَعُهَآ أَذٗىۗ وَٱللَّهُ غَنِيٌّ حَلِيمٞ ٢٦٣\n﴿قَوۡلًا مَّعۡرُوفًاۚ﴾: هو رد السائل بجميل من القول؛ كالدعاء له والتأنيس، (ومغفرة): عفو عن السائل إذا وجد منه جفاء، وقيل: مغفرة من الله لسبب الرد الجميل. ابن جزي: ١/١٧٢\nفي هذه الآية صورة من صور سمو الأخلاق في الإسلام، وضح ذلك.\nقَوۡلٞ مَّعۡرُوفٞ وَمَغۡفِرَةٌ خَيۡرٞ مِّن صَدَقَةٖ يَتۡبَعُهَآ أَذٗىۗ وَٱللَّهُ غَنِيٌّ حَلِيمٞ ٢٦٣\n(حليم) أي: لا يعاجل من عصاه، بل يرزقه وينصره، وهو يعصيه ويكفره. البقاعي: ١/٥١٧\nما دلالة ختم الآية بصفة (الحليم) لله -عز وجل-؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُبۡطِلُواْ صَدَقَٰتِكُم بِٱلۡمَنِّ وَٱلۡأَذَىٰ كَٱلَّذِي يُنفِقُ مَالَهُۥ رِئَآءَ ٱلنَّاسِ وَلَا يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۖ\nفيه تعريض بأن كُلًّا من الرياء والمن والأذى على الإنفاق من صفات الكفار، ولا بد للمؤمنين أن يجتنبوها. الألوسي: ٣/٣٥.\nما الفرق بين صدقة المخلص وصدقة المرائي؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُبۡطِلُواْ صَدَقَٰتِكُم بِٱلۡمَنِّ وَٱلۡأَذَىٰ\nويستدل بهذا على أن الأعمال السيئة تبطل الأعمال الصالحة... فكما أن الحسنات يذهبن السيئات، فالسيئات تبطل ما قابلها من الحسنات. السعدي: ١١٣.\nتدل الآية على خطورة الأعمال السيئة، وضح ذلك من الآية."],[45,"§البقرة\nwords\nبِرَبوَةٍمُرتَفَعٍ مِنَ الأَرضِ.\nفَطَلٌّمَطَرٌ خَفِيفٌ.\nتَيَمَّمُواتَقصِدُوا.\nتُغمِضُواتَتَغَاضَوا عَمَّا فِيهِ مِن رَدَاءَةٍ وَنَقصٍ.\ndeeds\nقل: \"اللهم إني أسألك الثبات في الأمر، والعزيمة على الرشد، والغنيمة من كل بر\".\nتذكر صدقةً أنت متردد فيها، وتصدق بها اليوم إرغامًا للشيطان.\nاسأل الله أن يرزقك الحكمة.\nguid\nاحرص على ضرب الأمثال فإنه يقرب المعاني إلى الأذهان.\nالأمر بالإنفاق اختبار لك فلا تنفق من الرديء، وتترك الجيد.\nالخوف من الفقر إنَّما هو وسوسة شيطانية؛ فلا تجعل الفقرَ سببًا لتركك الإنفاق والأعمال الصالحة.\nrefl\nوَمَثَلُ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمُ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِ وَتَثۡبِيتٗا مِّنۡ أَنفُسِهِمۡ\nمن راض نفسه بحملها على بذل المال -الذي هو شقيق الروح- وذلّت له خاضعة، وقل طمعها في اتباعه لشهواتها؛ فسهل عليه حملها على سائر العبادات. ومتى تركها -وهي مطبوعة على النقائص- زاد طمعًا في اتباع الشهوات ولزوم الدناءات. البقاعي: ١/٥١٨.\nبيّن من خلال الآية أهمية تربية النفس على النفقة والبذل.\nوَمَثَلُ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمُ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِ وَتَثۡبِيتٗا مِّنۡ أَنفُسِهِمۡ\nوذلك أن النفقة يعرض لها آفتان: إما أن يقصد الإنسان بها محمدة الناس ومدحهم، وهو الرياء، أو يخرجها على خور وضعف عزيمة وتردد. فهؤلاء سلموا من هاتين الآفتين، فأنفقوا ابتغاء مرضات الله، لا لغير ذلك من المقاصد، وتثبيتًا من أنفسهم. السعدي: ١١٤.\nما الآفات التي تعرض للمسلم حال إنفاقه؟\nوَمَثَلُ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمُ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِ وَتَثۡبِيتٗا مِّنۡ أَنفُسِهِمۡ كَمَثَلِ جَنَّةِۢ بِرَبۡوَةٍ أَصَابَهَا وَابِلٞ فَـَٔاتَتۡ أُكُلَهَا ضِعۡفَيۡنِ فَإِن لَّمۡ يُصِبۡهَا وَابِلٞ فَطَلّٞۗ\nأي: يخرجون الزكاة طيبة بها أنفسهم على يقين بالثواب، وتصديق بوعد الله، يعلمون أن ما أخرجوا خير لهم مما تركوا، وقيل: على يقين بإخلاف الله عليهم. البغوي: ١/٢٨٦.\nبيّن حال المؤمن عند إخراج الزكاة أو الصدقة.\nٱلشَّيۡطَٰنُ يَعِدُكُمُ ٱلۡفَقۡرَ وَيَأۡمُرُكُم بِٱلۡفَحۡشَآءِۖ\nوقدَّم وعد الشيطان على أمره؛ لأنه بالوعد يحصل الاطمئنان إليه، فإذا اطمأن إليه وخاف الفقر؛ تسلط عليه بالأمر. الألوسي: ٣/٤٠.\nلماذا قدم وعد الشيطان بالفقر على أمره بالفحشاء؟\nٱلشَّيۡطَٰنُ يَعِدُكُمُ ٱلۡفَقۡرَ وَيَأۡمُرُكُم بِٱلۡفَحۡشَآءِۖ وَٱللَّهُ يَعِدُكُم مَّغۡفِرَةٗ مِّنۡهُ وَفَضۡلٗاۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ ٢٦٨\nالشيطان له مدخل في التثبيط للإنسان عن الإنفاق في سبيل الله، وهو مع ذلك يأمر بالفحشاء، وهي المعاصي، والإنفاق فيها. القرطبي: ٤/٣٥٤.\nبيّن عمل الشيطان مع المؤمن إذا هم بالصدقة.\nيُؤۡتِي ٱلۡحِكۡمَةَ مَن يَشَآءُۚ وَمَن يُؤۡتَ ٱلۡحِكۡمَةَ فَقَدۡ أُوتِيَ خَيۡرٗا كَثِيرٗاۗ وَمَا يَذَّكَّرُ إِلَّآ أُوْلُواْ ٱلۡأَلۡبَٰبِ ٢٦٩\nقال بعض الحكماء: من أُعطي العلم والقرآن ينبغي أن يعرف نفسه، ولا يتواضع لأصحاب الدنيا لأجل دنياهم؛ فإنما أُعطي أفضل مما أُعطي أصحاب الدنيا؛ لأن الله تعالى سمى الدنيا متاعًا قليلًا، فقال: ﴿قُلۡ مَتَٰعُ ٱلدُّنۡيَا قَلِيلٞ﴾ [النساء: ٧٧]، وسمى العلم والقرآن: ﴿خَيۡرًا كَثِيرًاۗ﴾. القرطبي: ٤/٣٥٧.\nبيّن مكانة من أُعطيَ العلم والقرآن.\nيُؤۡتِي ٱلۡحِكۡمَةَ مَن يَشَآءُۚ وَمَن يُؤۡتَ ٱلۡحِكۡمَةَ فَقَدۡ أُوتِيَ خَيۡرٗا كَثِيرٗاۗ\nفصلاح القلب وحقه، والذي خلق من أجله هو: أن يعقل الأشياء؛ لا أقول أن يعلمها فقط؛ فقد يعلم الشيء من لا يكون عاقلًا له، بل غافلًا عنه مُلغيًا له. والذي يعقل الشيء هو الذي يقيده، ويضبطه، ويعيه، ويثبته في قلبه؛ فيكون وقت الحاجة إليه غنيًا، فيطابق عمله قوله، وباطنه ظاهره؛ وذلك هو الذي أوتي الحكمة. ابن تيمية: ١/٥٩٩.\nما علامة العقل والحكمة؟"],[46,"§البقرة\nwords\nأُحصِرُواحُبِسُوا عَن طَلَبِ الرِّزقِ لِلجِهَادِ.\nبِسِيمَاهُمبِعَلاَمَاتِهِم، وَآثَارِ الحَاجَةِ فِيهِم.\nإِلحَافًاإِلحَاحًا فِي السُّؤَالِ.\ndeeds\nحدد أناسًا ترى أن عليهم آثار الغفلة، ثم ألحَّ على الله بالدعاء بهدايتهم، لعل الله يكتب لك أجرهم.\nتذكر ذنبًا فعلته، ثم تصدق بصدقة؛ لعل الله يغفره لك.\nابحث عن عمل خير تأخر الناس في التبرع له، وبادر وأعلن عن صدقتك؛ ليحصل لك بذلك أجر الاقتداء بك.\nguid\nالسر والعلانية في الأعمال الصالحة تختلف باختلاف المصلحة المرجوَّة من كلٍّ منهما.\nالداعية يهتم بإيصال الدعوة على الوجه المطلوب، وليس مطالبًا بأن يستجيب الناس لدعوته.\nعود نفسك العفة، وترك سؤال الناس وطلب الحاجات منهم؛ فإن من استغنى بالله أغناه الله.\nrefl\nوَمَآ أَنفَقۡتُم مِّن نَّفَقَةٍ أَوۡ نَذَرۡتُم مِّن نَّذۡرٖ فَإِنَّ ٱللَّهَ يَعۡلَمُهُۥۗ وَمَا لِلظَّٰلِمِينَ مِنۡ أَنصَارٍ ٢٧٠\nففي إفهامه أن الله آخذ بيد السخي وبيد الكريم كلما عثر، فيجد له نصيرًا، ولا يجد الظالم بوضع القهر موضع البر ناصرًا. البقاعي: ١/٥٢٥.\nلم ختمت الآية بقوله سبحانه: ﴿وَمَا لِلظَّٰلِمِينَ مِنۡ أَنصَارٍ﴾ بعد الحث على الإنفاق؟\nإِن تُبۡدُواْ ٱلصَّدَقَٰتِ فَنِعِمَّا هِيَۖ وَإِن تُخۡفُوهَا وَتُؤۡتُوهَا ٱلۡفُقَرَآءَ فَهُوَ خَيۡرٞ لَّكُمۡۚ\nففي هذا: أن صدقة السر على الفقير أفضل من صدقة العلانية، وأمَّا إذا لم تؤت الصدقات الفقراء فمفهوم الآية أن السر ليس خيرًا من العلانية، فيرجع في ذلك إلى المصلحة؛ فإن كان في إظهارها إظهار شعائر الدين وحصول الاقتداء ونحوه فهو أفضل من الإسرار. السعدي: ١١٦.\nما الأفضل في الصدقات: السر أم العلانية؟\nوَإِن تُخۡفُوهَا وَتُؤۡتُوهَا ٱلۡفُقَرَآءَ فَهُوَ خَيۡرٞ لَّكُمۡۚ\nفيه دلالة إلى أن إسرار الصدقة أفضل من إظهارها؛ لأنه أبعد عن الرياء. ابن كثير: ١/٣٠٥.\nلم كان إسرار الصدقة أفضل من إظهارها؟\nوَمَا تُنفِقُونَ إِلَّا ٱبۡتِغَآءَ وَجۡهِ ٱللَّهِۚ\nلا تنفقوا إلا لأجل طلب وجه الله تعالى، أو إلا طالبين وجهه سبحانه؛ لا مؤذين، ولا مانين، ولا مرائين، ولا متيممين الخبيث. الألوسي: ٣/٤٦.\nاذكر أنواع الآفات التي تبطل الصدقة، أو تقلل أجرها.\nلِلۡفُقَرَآءِ ٱلَّذِينَ أُحۡصِرُواْ فِي سَبِيلِ ٱللَّهِ لَا يَسۡتَطِيعُونَ ضَرۡبٗا فِي ٱلۡأَرۡضِ يَحۡسَبُهُمُ ٱلۡجَاهِلُ أَغۡنِيَآءَ مِنَ ٱلتَّعَفُّفِ تَعۡرِفُهُم بِسِيمَٰهُمۡ لَا يَسۡٔلُونَ ٱلنَّاسَ إِلۡحَافٗاۗ وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ ٢٧٣\nأي: يظن الجاهل بحالهم أنهم أغنياء؛ لقلة سؤالهم، والتعفف هنا هو عن الطلب. ﴿تَعۡرِفُهُم بِسِيمَٰهُمۡ﴾: علامة وجوههم؛ وهي ظهور الجهد والفاقة، وقلة النعمة، وقيل: الخشوع، وقيل: السجود. ﴿لَا يَسۡـَٔلُونَ ٱلنَّاسَ إِلۡحَافًاۗ﴾: الإلحاف هو الإلحاح في السؤال؛ والمعنى: أنهم إذا سألوا يتلطفون ولا يلحون. وقيل: هو نفي السؤال والإلحاح معًا. ابن جزي: ١/١٢٧.\nما الصفات التي امتدح الله بها فقراء المؤمنين في هذه الآية؟\nلِلۡفُقَرَآءِ ٱلَّذِينَ أُحۡصِرُواْ فِي سَبِيلِ ٱللَّهِ لَا يَسۡتَطِيعُونَ ضَرۡبٗا فِي ٱلۡأَرۡضِ يَحۡسَبُهُمُ ٱلۡجَاهِلُ أَغۡنِيَآءَ مِنَ ٱلتَّعَفُّفِ\nوإنَّما خص فقراء المهاجرين لأنه لم يكن هناك سواهم، وهم أهل الصُّفَّة، وكانوا نحوًا من أربع مئة رجل؛ وذلك أنهم كانوا يَقْدَمون فقراء على رسول الله -صلى الله عليه وسلم-، وما لهم أهل ولا مال، فبُنيت لهم صُفَّة في مسجد رسول الله -صلى الله عليه وسلم-، فقيل لهم: أهل الصُّفَّة. القرطبي: ٤/٣٧١.\nما سبب فقر أهل الصُّفَّة؟\nٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُم بِٱلَّيۡلِ وَٱلنَّهَارِ سِرّٗا وَعَلَانِيَةٗ فَلَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ٢٧٤\nقدم الليل على النهار، والسر على العلانية للإيذان؛ بمزية الإخفاء على الإظهار. الألوسي: ٣/٤٧.\nلماذا قدم الليل على النهار، والسر على العلانية؟"],[47,"§البقرة\nwords\nيَتَخَبَّطُهُيَصرَعُهُ.\nالمَسِّالجُنُونِ.\nيَمحَقُيَنقُصُ وَيُذهِبُ البَرَكَةَ.\nوَيُربِييَزِيدُ، وَيُنَمِّي.\nفَأذَنُوااستَيقِنُوا.\ndeeds\nأرسل رسالة تحذر فيها من خطر الربا على صاحبه، وعلى المسلمين.\nحافظ على الصلوات الخمس مع الجماعة.\nساعد معسرًا، أو اشفع له في قضاء دينه.\nguid\nالذي يتعامل بالربا فقد الحكمة التي تقوده إلى طريق الحق.\nالمال المحرم ممحوق البركة، وهو ضرر على صاحبه، والصدقة سبب للسعادة في الدنيا والآخرة.\nهذه الآية تحتاج إلى ترديد لتستقر في القلوب، ويفيض أثرها على الجوارح.\nrefl\nٱلَّذِينَ يَأۡكُلُونَ ٱلرِّبَوٰاْ لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ ٱلَّذِي يَتَخَبَّطُهُ ٱلشَّيۡطَٰنُ مِنَ ٱلۡمَسِّۚ\nيُبعث كالمجنون؛ عقوبة له، وتمقيتًا عند جميع أهل المحشر. القرطبي: ٤/٣٩٠.\nكيف يُبعث المرابي يوم القيامة؟\nيَمۡحَقُ ٱللَّهُ ٱلرِّبَوٰاْ وَيُرۡبِي ٱلصَّدَقَٰتِۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ ٢٧٦\nولا بد من مناسبة في ختم هذه الآية بهذه الصفة؛ وهي أن المرابي لا يرضى بما قسم الله له من الحلال، ولا يكتفي بما شرع له من الكسب المباح، فهو يسعى في أكل أموال الناس بالباطل بأنواع المكاسب الخبيثة، فهو جحود لما عليه من النعمة، ظلوم آثم، يأكل أموال الناس بالباطل. ابن كثير: ١/٣١٢.\nلماذا وصف آكل الربا بأنه كفار أثيم؟\nيَمۡحَقُ ٱللَّهُ ٱلرِّبَوٰاْ وَيُرۡبِي ٱلصَّدَقَٰتِۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ ٢٧٦\nعن ابن عباس -رضي الله عنهما-: (يمحق الله الربا) يعني: لا يقبل منه صدقةً ولا جهادًا ولا حجًّا ولا صلةً. ﴿وَيُرۡبِي ٱلصَّدَقَٰتِۗ﴾ أي: يثمرها ويبارك فيها في الدنيا، ويضاعف بها الأجر والثواب في العقبى. ﴿وَٱللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ﴾ بتحريم الربا (أثيم) فاجر بأكله. البغوي: ١/٣٠٢.\nما أثر الربا على آكله؟\nيَمۡحَقُ ٱللَّهُ ٱلرِّبَوٰاْ وَيُرۡبِي ٱلصَّدَقَٰتِۗ\nوهذا لأن الجزاء من جنس العمل؛ فإن المرابي قد ظلم الناس، وأخذ أموالهم على وجه غير شرعي؛ فجوزي بذهاب ماله، والمحسن إليهم بأنواع الإحسان ربه أكرم منه؛ فيحسن عليه كما أحسن على عباده. السعدي: ١١٧.\nلماذا كان جزاء المرابي محق ماله، وجزاء المحسن تنمية حسناته؟\nإِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَأَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ لَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ٢٧٧\nوخص الصلاة والزكاة بالذكر، وقد تضمنهما عمل الصالحات؛ تشريفًا لهما، وتنبيهًا على قدرهما؛ إذ هما رأس الأعمال: الصلاة في أعمال البدن، والزكاة في أعمال المال. القرطبي: ٤/٤٠٣.\nلم خص الله تعالى الصلاة والزكاة بالذكر؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَذَرُواْ مَا بَقِيَ مِنَ ٱلرِّبَوٰٓاْ إِن كُنتُم مُّؤۡمِنِينَ ٢٧٨\nالربا والإيمان لا يجتمعان، وأكثر بلايا هذه الأمة -حتى أصابها ما أصاب بني إسرائيل من البأس الشنيع والانتقام بالسنين- إنَّما هو مِن عملِ مَن عمِلَ بالربا. البقاعي: ١/٥٤١.\nلماذا جاء التشديد بتحريم الربا؟\nوَٱتَّقُواْ يَوۡمٗا تُرۡجَعُونَ فِيهِ إِلَى ٱللَّهِۖ ثُمَّ تُوَفَّىٰ كُلُّ نَفۡسٖ مَّا كَسَبَتۡ وَهُمۡ لَا يُظۡلَمُونَ ٢٨١\nمن علم أنه راجع إلى الله فمجازيه على الصغير والكبير، والجلي والخفي، وأن الله لا يظلمه مثقال ذرة؛ أوجب له الرغبة والرهبة. السعدي: ١١٧-١١٨.\nما ثمرة علم الإنسان أنه راجع إلى ربه؟"],[48,"§البقرة\nwords\nوَلاَ يَأبَلاَ يَمتَنِع.\nوَليُملِلِلِيُملِ، وَيُقِرَّ.\nيَبخَسيَنقُص.\nسَفِيهًامَحجُورًا عَلَيهِ؛ لِتَبذِيرِهِ.\nضَعِيفًاكَالصَّغِيرِ وَالمَجنُونِ.\nتَسأَمُواتَمَلُّوا.\nوَأَقوَمُ لِلشَّهَادَةِأَعظَمُ عَونًا عَلَى إِقَامَةِ الشَّهَادَةِ.\ndeeds\nبادر اليوم بكتابة كل دين لك أو عليك؛ لكي لا تضيع حقك وحق ورثتك، أو حقوق الناس.\nأقرض شخصًا محتاجًا مبلغًا من المال، واكتب ذلك.\nحدد مهارة مَنَّ الله بها عليك، وعلِّمها غيرك شكرًا لله تعالى.\nguid\nضبط أحكام الأموال طريق لضبط أعمال القلوب، وضبط أعمال القلوب فيه صلاح الدين والدنيا.\nعلى من خصه الله بنعمة يحتاج الناس إليها أن يبذلها لهم؛ فإن ذلك من شكره لله على هذه النعمة.\nتقوى الله هي السبب الأول للعلم.\nrefl\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا تَدَايَنتُم بِدَيۡنٍ إِلَىٰٓ أَجَلٖ مُّسَمّٗى فَٱكۡتُبُوهُۚ\nالأمر بالكتب ندب إلى حفظ الأموال وإزالة الريب، وإذا كان الغريم تقيًا فما يضره الكتاب. القرطبي: ٤/٤٣١.\nلم أمر الله تعالى بالكتابة في الدين ونحوه من المعاملات؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا تَدَايَنتُم بِدَيۡنٍ إِلَىٰٓ أَجَلٖ مُّسَمّٗى فَٱكۡتُبُوهُۚ\nالأمر بكتابة جميع عقود المداينات... لشدة الحاجة إلى كتابتها؛ لأن بدون الكتابة يدخلها من الغلط، والنسيان، والمنازعة، والمشاجرة شر عظيم. السعدي: ١١٨.\nلماذا أمر الشرع بكتابة الديون؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا تَدَايَنتُم بِدَيۡنٍ إِلَىٰٓ أَجَلٖ مُّسَمّٗى فَٱكۡتُبُوهُۚ\nوالتداين من أعظم أسباب رواج المعاملات؛ لأن المقتدر على تنمية المال قد يعوزه المال؛ فيضطر إلى التداين ليظهر مواهبه في التجارة، أو الصناعة، أو الزراعة، ولأن المترفه قد ينضب المال من بين يديه، وله قِبَل به بعد حين، فإذا لم يتداين اختل نظام ماله. ابن عاشور: ٣/٩٨.\nما حكمة إباحة التداين في الإسلام؟\nوَلۡيَكۡتُب بَّيۡنَكُمۡ كَاتِبُۢ بِٱلۡعَدۡلِۚ\nأن يكون الكاتب عارفًا بكتابة الوثائق، وما يلزم فيها كل واحد منهما، وما يحصل به التوثق؛ لأنه لا سبيل إلى العدل إلا بذلك. السعدي: ١١٨.\nمن الكاتب المعتبر في كتابة الديون؟\nفَإِن لَّمۡ يَكُونَا رَجُلَيۡنِ فَرَجُلٞ وَٱمۡرَأَتَانِ مِمَّن تَرۡضَوۡنَ مِنَ ٱلشُّهَدَآءِ\nوالعدالة شرط؛ وهي أن يكون الشاهد مجتنبًا للكبائر، غير مصرٍّ على الصغائر. والمروءة شرط؛ وهي ما يتصل بآداب النفس مما يعلم أن تاركه قليل الحياء؛ وهي: حسن الهيئة، والسيرة، والعشرة، والصناعة. فإن كان الرجل يظهر من نفسه شيء منها ما يستحي أمثاله من إظهاره في الأغلب؛ يعلم به قلة مروءته، وتُرد شهادته. البغوي: ١/٣٠٩.\nما المقصود بصفتي المروءة والعدالة؟\nوَٱتَّقُواْ ٱللَّهَۖ وَيُعَلِّمُكُمُ ٱللَّهُۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ ٢٨٢\nوعد من الله تعالى بأن من اتقاه علَّمه؛ أي: يجعل في قلبه نورًا يفهم به ما يُلقى إليه، وقد يجعل الله في قلبه ابتداءً فرقانًا؛ أي: فيصلًا يفصل به بين الحق والباطل. القرطبي: ٤/٤٦٤.\nكيف ينال العبد العلم من الله تعالى؟\nوَٱتَّقُواْ ٱللَّهَۖ وَيُعَلِّمُكُمُ ٱللَّهُۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ ٢٨٢\nوختم آيات هذه المعاملات بصفة العلم بعد الأمر بالتقوى في غاية المناسبة -لما يفعله المتعاملون من الحيل التي يجتلب كل منهم بها الحظ لنفسه- والترغيب في امتثال ما أمرهم به. البقاعي: ١/٥٤٩.\nلماذا ختم آيات هذه المعاملات بصفة العلم بعد الأمر بالتقوى؟"],[49,"§البقرة\nwords\nفَرِهَانٌ مَقبُوضَةٌهُوَ أَن يَدفَعَ لِصَاحِبِ الحَقِّ شَيئًا؛ لِيُضمَنَ حَقُّهُ حَتَّى يَرُدَّ المَدِينُ الدَّينَ.\nإِصرًامَشَقَّةً وَثِقَلًا.\ndeeds\nاقرأ الآيتين آخر البـقرة في ليـلتك؛ ففيهما كـفـاية لـمن قرأهما.\nاحرص اليوم بعد فراغك من أي طاعة وعمل خير أن تسأل الله تعالى المغفرة.\nاعمل اليوم عملًا صالحًا بلسانك، أو مالك، أو جوارحك، ثم ادع بدعاء، فهو أرجى لقبول دعائك.\nguid\nكاتم الشهادة آثم قلبه، فكيف بمن يكذب في الشهادة.\nالسمع والطاعة لله سبب لنيل مغفرته سبحانه.\nموالاة الله -سبحانه وتعالى- سبب للانتصار على الأعداء.\nrefl\nفَلۡيُؤَدِّ ٱلَّذِي ٱؤۡتُمِنَ أَمَٰنَتَهُۥ وَلۡيَتَّقِ ٱللَّهَ رَبَّهُۥۗ\nوقد أمر سبحانه بالتقوى عند الوفاء حسبما أمر بها عند الإقرار؛ تعظيمًا لحقوق العباد، وتحذيرًا عما يوجب وقوع الفساد. الألوسي: ٣/٦٣.\nلماذا أمر سبحانه بالتقوى عند الوفاء، وأمر بها ثانيةً عند الإقرار؟\nوَمَن يَكۡتُمۡهَا فَإِنَّهُۥٓ ءَاثِمٞ قَلۡبُهُۥۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ عَلِيمٞ ٢٨٣\nخص القلب بالإثم؛ إذ الكتم من أفعاله، وإذ هو المضغة التي بصلاحها يصلح الجسد كله. القرطبي: ٤/٤٧٨.\nلماذا خص الله تعالى ذكر القلب في هذه الآية؟\nوَإِن كُنتُمۡ عَلَىٰ سَفَرٖ وَلَمۡ تَجِدُواْ كَاتِبٗا فَرِهَٰنٞ مَّقۡبُوضَةٞۖ فَإِنۡ أَمِنَ بَعۡضُكُم بَعۡضٗا فَلۡيُؤَدِّ ٱلَّذِي ٱؤۡتُمِنَ أَمَٰنَتَهُۥ وَلۡيَتَّقِ ٱللَّهَ رَبَّهُۥۗ وَلَا تَكۡتُمُواْ ٱلشَّهَٰدَةَۚ وَمَن يَكۡتُمۡهَا فَإِنَّهُۥٓ ءَاثِمٞ قَلۡبُهُۥۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ عَلِيمٞ ٢٨٣\nوقد اشتملت هذه الأحكام الحسنة التي أرشد الله عباده إليها على حكم عظيمة ومصالح عميمة؛ دلت على أن الخلق لو اهتدوا بإرشاد الله لصلحت دنياهم مع صلاح دينهم؛ لاشتمالها على العدل والمصلحة، وحفظ الحقوق، وقطع المشاجرات والمنازعات، وانتظام أمر المعاش. السعدي: ١١٩-١٢٠.\nما الذي يصلح دين الخلق ودنياهم ؟\nوَقَالُواْ سَمِعۡنَا وَأَطَعۡنَاۖ غُفۡرَانَكَ رَبَّنَا وَإِلَيۡكَ ٱلۡمَصِيرُ ٢٨٥\nوتقديم السمع والطاعة على طلب الغفران لما أن تقدم الوسيلة على المسئول أقرب إلى الإجابة والقبول. الألوسي: ٣/٦٩.\nلماذا قدم السمع والطاعة على طلب الغفران؟\nلَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا وُسۡعَهَاۚ\nفأصل الأوامر والنواهي ليست من الأمور التي تشق على النفوس، بل هي غذاء للأرواح، ودواء للأبدان، وحمية عن الضرر؛ فالله تعالى أمر العباد بما أمرهم به رحمةً وإحسانًا. السعدي: ١٢٠.\nتكاليف الشريعة كلها رحمة وإحسان، دلل على هذا من خلال هذه الآية.\nلَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا وُسۡعَهَاۚ لَهَا مَا كَسَبَتۡ وَعَلَيۡهَا مَا ٱكۡتَسَبَتۡۗ\nجاءت العبارة في الحسنات بـــــ(لها) من حيث هي مما يفرح المرء بكسبه ويسر بها، فتضاف إلى ملكه. وجاءت في السيئات بـــــــ(عليها) من حيث هي أثقال وأوزار، ومتحملات صعبة، وهذا كما تقول: \"لي مال\"، و\"علي دين\". القرطبي: ٤/٥٠٠.\nما سر التعبير القرآني في ذكر الحسنات بــ (لها)، والسيئات بــــــ (عليها)؟\nوَٱعۡفُ عَنَّا وَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَآۚ\nوقوله: ﴿وَٱعۡفُ عَنَّا﴾ أي: فيما بيننا وبينك مما تعلمه من تقصيرنا وزللنا. ﴿وَٱغۡفِرۡ لَنَا﴾ أي: فيما بيننا وبين عبادك؛ فلا تظهرهم على مساوينا وأعمالنا القبيحة. (وارحمنا) أي: فيما يستقبل؛ فلا توقعنا -بتوفيقك- في ذنب آخر. ولهذا قالوا: إن المذنب محتاج إلى ثلاثة أشياء: أن يعفو الله عنه فيما بينه وبينه، وأن يستره عن عباده؛ فلا يفضحه به بينهم، وأن يعصمه؛ فلا يوقعه في نظيره. ابن كثير: ١/٣٢٤.\nما الأمور الثلاثة التي يحتاج إليها المذنب؟"],[50,"§آل عمران\nwords\nالقَيُّومُالقَائِمُ عَلَى كُلِّ شَيءٍ.\nمُحكَمَاتٌوَاضِحَاتُ الدَّلاَلَةِ.\nأُمُّ الكِتَابِأَصلُ الكِتَابِ الَّذِي يُرجَعُ إِلَيهِ عِندَ الاِشتِبَاهِ.\nمُتَشَابِهَاتٌخَفِيَّاتٌ، لاَ يَتَعَيَّنُ المُرَادُ مِنهَا إِلاَّ بِرَدِّهَا إِلَى المُحكَمَاتِ.\nزَيغٌمَرَضٌ، وانحِرَافٌ.\nتَأوِيلِهِتَفسِيرِهِ أَو مَعرِفَةِ حَقِيقَتِهِ.\ndeeds\nضع برنامجًا تتدبر فيه سورةَ آل عمران؛ حتى تحاجّ عنك يوم القيامة.\nأكثر اليوم من قولك: \"رب زدني علمًا\".\nأكثر اليوم من سؤال الله الثبات على الهداية والحق.\nguid\nإذا أردت أن تعمل معصية فهل تجد مكانًا تختبئ فيه عن نظر الله -عز وجل-.\nصفات خلقتك إنَّما هي من الله -سبحانه وتعالى-؛ فارض بما قسمه الله لك.\nاعلم أن ترك الدليل الواضح والاستدلال بلفظ متشابه هو طريق أهل الزيغ.\nrefl\nنَزَّلَ عَلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ وَأَنزَلَ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ ٣\nوإنَّما قال: (وأنزل التوراة والإنجيل) لأن التوراة والإنجيل أُنزلا جملة واحدة، وقال في القرآن: (نزَّل) لأنه نزل مفصلًا؛ والتنزيل للتكثير. البغوي: ١/٣٢٠.\nلماذا قال في التوراة والإنجيل (وأنزل)، وفي القرآن (نزَّل)؟\nمُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ\nمن الكتب السابقة؛ فهو المزكي لها؛ فما شهد له فهو المقبول، وما رده فهو المردود، وهو المطابق لها في جميع المطالب التي اتفق عليها المرسلون، وهي شاهدة له بالصدق؛ فأهل الكتاب لا يمكنهم التصديق بكتبهم إن لم يؤمنوا به؛ فإنَّ كفرهم به ينقض إيمانهم بكتبهم. السعدي: ١٢١.\nدلت هذه الآية على أن القرآن حاكمٌ على غيره من الكتب، فكيف ذلك؟\nهُوَ ٱلَّذِيٓ أَنزَلَ عَلَيۡكَ ٱلۡكِتَٰبَ مِنۡهُ ءَايَٰتٞ مُّحۡكَمَٰتٌ هُنَّ أُمُّ ٱلۡكِتَٰبِ وَأُخَرُ مُتَشَٰبِهَٰتٞۖ\nإنَّما أنزل المتشابه لذلك؛ ليظهر فضل العلماء، ويزداد حرصهم على الاجتهاد فى تدبره، وتحصيل العلوم التى نيط بها استنباط ما أريد به من الأحكام الحقيقية؛ فينالوا بذلك وبإتعاب القرائح واستخراج المقاصد الرائقة والمعاني اللائقة المدارج العالية. الألوسي: ٣/٨٣.\nما الحكمة من إنزال المتشابه في القرآن الكريم؟\nفَأَمَّا ٱلَّذِينَ فِي قُلُوبِهِمۡ زَيۡغٞ فَيَتَّبِعُونَ مَا تَشَٰبَهَ مِنۡهُ ٱبۡتِغَآءَ ٱلۡفِتۡنَةِ\n(زيغ) أي: ضلال وخروج عن الحق إلى الباطل. ﴿فَيَتَّبِعُونَ مَا تَشَٰبَهَ مِنۡهُ﴾ أي: إنَّما يأخذون منه بالمتشابه الذي يمكنهم أن يحرفوه إلى مقاصدهم الفاسدة، وينزلوه عليها؛ لاحتمال لفظه لما يصرفونه، فأما المحكم فلا نصيب لهم فيه؛ لأنه دافع لهم، وحجة عليهم؛ ولهذا قال الله تعالى: ﴿ٱبۡتِغَآءَ ٱلۡفِتۡنَةِ﴾ أي: الإضلال لأتباعهم؛ إيهامًا لهم أنهم يحتجون على بدعتهم بالقرآن وهو حجة عليهم لا لهم. ابن كثير: ١/٣٣٦.\nما موقف المبتدعة من الآيات المتشابهة؟\nفَأَمَّا ٱلَّذِينَ فِي قُلُوبِهِمۡ زَيۡغٞ فَيَتَّبِعُونَ مَا تَشَٰبَهَ مِنۡهُ ٱبۡتِغَآءَ ٱلۡفِتۡنَةِ وَٱبۡتِغَآءَ تَأۡوِيلِهِۦۖ\nبيّن -سبحانه وتعالى- أنه لا يضل بحرف المتشابه إلا ذوو الطبع العوج؛ الذين لم ترسخ أقدامهم في الدين، ولا استنارت معارفهم في العلم. البقاعي: ٢/٢٢.\nمن الذي يضل في المتشابه؟\nوَٱلرَّٰسِخُونَ فِي ٱلۡعِلۡمِ يَقُولُونَ ءَامَنَّا بِهِۦ كُلّٞ مِّنۡ عِندِ رَبِّنَاۗ وَمَا يَذَّكَّرُ إِلَّآ أُوْلُواْ ٱلۡأَلۡبَٰبِ ٧\nمدحًا للراسخين بجودة الذهن وحسن النظر؛ لما أنهم قد تجردت عقولهم عمَّا يغشاها من الركون إلى الأهواء الزائغة المكدرة لها، واستعدوا إلى الاهتداء إلى معالم الحق، والعروج إلى معارج الصدق. الألوسي: ٣/٨٣.\nما دلالة قوله تعالى: ﴿وَمَا يَذَّكَّرُ إِلَّآ أُوْلُواْ ٱلۡأَلۡبَٰبِ﴾؟\nرَبَّنَا لَا تُزِغۡ قُلُوبَنَا بَعۡدَ إِذۡ هَدَيۡتَنَا وَهَبۡ لَنَا مِن لَّدُنكَ رَحۡمَةًۚ إِنَّكَ أَنتَ ٱلۡوَهَّابُ ٨\nفلله رحمة قد عمت الخلق؛ برهم وفاجرهم، سعيدهم وشقيهم، ثم له رحمة خص بها المؤمنين خاصةً؛ وهي رحمة الإيمان، ثم له رحمة خص بها المتقين؛ وهي رحمة الطاعة لله تعالى، ولله رحمة خص بها الأولياء نالوا بها الولاية، وله رحمة خص بها الأنبياء نالوا بها النبوة، وقال الراسخون في العلم: ﴿وَهَبۡ لَنَا مِن لَّدُنكَ رَحۡمَةًۚ﴾. ابن تيمية: ٢/٣٤.\nاذكر أنواعًا من رحمة الله تعالى بالخلق."],[51,"§آل عمران\nwords\nكَدَأبِكَشَأنِ وَعَادَةِ.\nوَالقَنَاطِيرِ المُقَنطَرَةِالأَموَالِ الكَثِيرَةِ مِنَ الذَّهَبِ وَالفِضَّةِ.\nالمُسَوَّمَةِالحِسَانِ.\nوَالحَرثِالأَرضِ المُتَّخَذَةِ لِلزِّرَاعَةِ.\nالمَآبِالمَرجِعِ وَالثَّوَابِ.\ndeeds\nتذكر ذنبًا كبيرًا فعلته، وبادر بالاستغفار منه.\nأرسل رسالة تذكر فيها أن العاقبة في نهاية المعركة للمتقين.\nوأنت تستمتع بملذات الدنيا المباحة سل الله ألا يتعلق قلبك بها.\nguid\nبالعمل الصالح تدخل الجنة، وليس بكثرة الأموال والأولاد؛ فاشتغل بما ينفعك.\nالذنوب طريق العذاب العاجل والآجل.\nمن أفضل الوسائل لمواجهة المغريات والشهوات: تذكر الآخرة ووعد الله تعالى لمن صبر عن تلك المغريات.\nrefl\nإِنَّ ٱلَّذِينَ كَفَرُواْ لَن تُغۡنِيَ عَنۡهُمۡ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُم مِّنَ ٱللَّهِ شَيۡٔاۖ وَأُوْلَٰٓئِكَ هُمۡ وَقُودُ ٱلنَّارِ ١٠\nهؤلاء الكفار قد ألهتهم أموالهم وأولادهم عن الله تعالى والنظر فيما ينبغي له إلى حيث يخيل للرائي أنهم ممن يعتقد أنها تسُد مسدَّ رحمة الله تعالى وطاعته. الألوسي: ٣/٩٣.\nلماذا بيّن الله تعالى أن الكفار لن تغني عنهم أموالهم ولا أولادهم؟\nوَٱللَّهُ يُؤَيِّدُ بِنَصۡرِهِۦ مَن يَشَآءُۚ إِنَّ فِي ذَٰلِكَ لَعِبۡرَةٗ لِّأُوْلِي ٱلۡأَبۡصَٰرِ ١٣\nأي: إن النصر بمشيئة الله؛ لا بالقلة، ولا بالكثرة؛ فإن فئة المسلمين غلبت فئة الكافرين مع أنهم كانوا أكثر منهم. ابن جزي: ١/١٣٨.\nهل ميزان النصر الحقيقي هو الكثرة وقوة السلاح؟ وضح ذلك.\nوَٱللَّهُ يُؤَيِّدُ بِنَصۡرِهِۦ مَن يَشَآءُۚ إِنَّ فِي ذَٰلِكَ لَعِبۡرَةٗ لِّأُوْلِي ٱلۡأَبۡصَٰرِ ١٣\nلو نظر الناظر إلى مجرد الأسباب الظاهرة والعدد والعُدد لجزم بأن غلبة هذه الفئة القليلة لتلك الفئة الكثيرة من أنواع المحالات، ولكن وراء هذا السبب المُشاهد بالأبصار سبب أعظم منه لا يدركه إلا أهل البصائر والإيمان بالله والتوكل على الله والثقة بكفايته؛ وهو نصره وإعزازه لعباده المؤمنين على أعدائه الكافرين. السعدي: ١٢٣.\nما وجه ختم الآية بقوله: ﴿إِنَّ فِي ذَٰلِكَ لَعِبۡرَةً لِّأُوْلِي ٱلۡأَبۡصَٰرِ﴾؟\nزُيِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَٰتِ مِنَ ٱلنِّسَآءِ وَٱلۡبَنِينَ وَٱلۡقَنَٰطِيرِ ٱلۡمُقَنطَرَةِ مِنَ ٱلذَّهَبِ وَٱلۡفِضَّةِ وَٱلۡخَيۡلِ ٱلۡمُسَوَّمَةِ وَٱلۡأَنۡعَٰمِ وَٱلۡحَرۡثِۗ ذَٰلِكَ مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَٱللَّهُ عِندَهُۥ حُسۡنُ ٱلۡمَٔابِ ١٤\nوفائدة هذا التمثيل أن الجنة لا تُنال إلا بترك الشهوات، وفطام النفس عنها. القرطبي: ٥/٤٣.\nما المناسبة بين ذكر الشهوات وحسن المآب؟\nزُيِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَٰتِ مِنَ ٱلنِّسَآءِ وَٱلۡبَنِينَ وَٱلۡقَنَٰطِيرِ ٱلۡمُقَنطَرَةِ\nفبدأ بالنساء؛ لأن الفتنة بهن أشد، كما ثبت في الصحيح أنه -عليه السلام- قال: «ما تركت بعدي فتنة أضر على الرجال من النساء»، فأما إذا كان القصد بهن الإعفاف وكثرة الأولاد؛ فهذا مطلوب مرغوب فيه مندوب إليه. ابن كثير: ١/٣٣٢.\nلماذا بدأ بذكر النساء في أنواع الشهوات؟\nزُيِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَٰتِ مِنَ ٱلنِّسَآءِ وَٱلۡبَنِينَ وَٱلۡقَنَٰطِيرِ ٱلۡمُقَنطَرَةِ مِنَ ٱلذَّهَبِ وَٱلۡفِضَّةِ وَٱلۡخَيۡلِ ٱلۡمُسَوَّمَةِ وَٱلۡأَنۡعَٰمِ وَٱلۡحَرۡثِۗ ذَٰلِكَ مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ\nوخص هذه الأمور المذكورة؛ لأنها أعظم شهوات الدنيا، وغيرها تبع لها. السعدي: ١٢٤.\nلماذا خُصَّت الشهوات بهذه المذكورات في الآية؟\nقُلۡ أَؤُنَبِّئُكُم بِخَيۡرٖ مِّن ذَٰلِكُمۡۖ لِلَّذِينَ ٱتَّقَوۡاْ عِندَ رَبِّهِمۡ جَنَّٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا وَأَزۡوَٰجٞ مُّطَهَّرَةٞ وَرِضۡوَٰنٞ مِّنَ ٱللَّهِۗ\nبدأ سبحانه في هذه الآية أولًا بذكر المقر وهو الجنات، ثم ثنى بذكر ما يحصل به الأنس التام؛ وهو الأزواج المطهرة، ثم ثلث بذكر ما هو الإكسير الأعظم والروح لفؤاد الواله المغرم؛ وهو رضا الله -عز وجل-. الألوسي: ٣/١٠١.\nما الجزاء الذي أعده الله للمتقين؟"],[52,"§آل عمران\nwords\nوَالقَانِتِينَالمُطِيعِينَ للهِ.\nقَائِمًا بِالقِسطِمُقِيمًا لِلعَدلِ فِي كُلِّ أَمرٍ.\nبَغيًاحَسَدًا وَعُدوَانًا.\nحَبِطَتبَطَلَت.\ndeeds\nابحث عن محبوب دنيوي تعلقت به نفسك وحاول أن تصبر عنه هذا اليوم تربية لنفسك.\nادع الله بحاجة تريدها، وقدم قبل دعائك عملًا صالحًا؛ فهو أرجى لقبوله.\nصلِّ اليوم بالليل ولو ركعات قليلة، ثم استغفر الله تعالى.\nguid\nتواضع لله تعالى؛ فمهما بلغت في مقامات العبودية فأنت مقصر في حق الله تعالى.\nعلم التوحيد أهم العلوم الشرعية؛ فاحرص على أن يكون لك اطلاعٌ كبيرٌ فيه.\nأهل الكتاب لم يؤتوا من قلة علم وضآلة معرفة، وإنَّما كان هلاكهم لأنهم وظفوا ما عندهم من علوم ومعارف للبغي بينهم بسبب الحسد.\nrefl\nٱلصَّٰبِرِينَ وَٱلصَّٰدِقِينَ وَٱلۡقَٰنِتِينَ وَٱلۡمُنفِقِينَ وَٱلۡمُسۡتَغۡفِرِينَ بِٱلۡأَسۡحَارِ ١٧\nتخصيص الأسحار بالاستغفار لأن الدعاء فيها أقرب إلى الإجابة؛ إذ العبادة حينئذ أشق، والنفس أصفى، والروع أجمع. الألوسي:٣/١٠٢.\nلماذا خصص الأسحار بالاستغفار؟\nٱلصَّٰبِرِينَ وَٱلصَّٰدِقِينَ وَٱلۡقَٰنِتِينَ وَٱلۡمُنفِقِينَ وَٱلۡمُسۡتَغۡفِرِينَ بِٱلۡأَسۡحَارِ ١٧\nكانوا يحيون الليل صلاة، ثم يقعدون في السحر يستغفرون؛ فيختمون قيام الليل بالاستغفار. ابن تيمية:٢/٣٩.\nبِمَ تختم أكثر العبادات؟\nشَهِدَ ٱللَّهُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا هُوَ وَٱلۡمَلَٰٓئِكَةُ وَأُوْلُواْ ٱلۡعِلۡمِ قَآئِمَۢا بِٱلۡقِسۡطِۚ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ١٨\nوفي هذا دليل على أن أشرف الأمور علم التوحيد؛ لأن الله شهد به بنفسه، وأشهد عليه خواص خلقه؛ والشهادة لا تكون إلا عن علم ويقين بمنزلة المشاهدة للبصر. السعدي: ١٢٥.\nما منزلة علم التوحيد؟ وكيف تستدل على ما تقول بهذه الآية؟\nشَهِدَ ٱللَّهُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا هُوَ وَٱلۡمَلَٰٓئِكَةُ وَأُوْلُواْ ٱلۡعِلۡمِ قَآئِمَۢا بِٱلۡقِسۡطِۚ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ١٨\nفي هذه الآية دليل على شرف العلم من وجوه كثيرة؛ منها: أن الله قرن شهادة العلماء بشهادته وشهادة ملائكته، وكفى بذلك فضلًا... ومنها: أنه تعالى جعلهم شهداء وحجة على الناس، وألزم الناس العمل بالأمر المشهود به؛ فيكونون هم السبب في ذلك، فيكون كل من عمل بذلك نالهم من أجره، وذلك فضل الله يؤتيه من يشاء، ومنها: أن إشهاده تعالى أهل العلم يتضمن ذلك تزكيتهم وتعديلهم، وأنهم أمناء على ما استرعاهم عليه. السعدي: ١٢٥.\nدلت الآية على شرف العلم والعلماء من عدة وجوه، بَيِّنها.\nإِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلۡإِسۡلَٰمُۗ وَمَا ٱخۡتَلَفَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ بَغۡيَۢا بَيۡنَهُمۡۗ وَمَن يَكۡفُرۡ بِـَٔايَٰتِ ٱللَّهِ فَإِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ ١٩\nسبب الاجتماع والألفة: جمع الدين والعمل به كله؛ وهو عبادة الله وحده لا شريك له كما أمر به باطنًا وظاهرًا. وسبب الفرقة: ترك حظٍّ مما أُمر العبد به، والبغي بينهم. ونتيجة الجماعة: رحمة الله، ورضوانه، وصلواته، وسعادة الدنيا والآخرة، وبياض الوجوه. ونتيجة الفرقة: عذاب الله، ولعنته، وسواد الوجوه، وبراءة الرسول -صلى الله عليه وسلم- منهم. ابن تيمية: ٢/٥٥.\nما سبب الاجتماع؟ وما سبب الفرقة في الأمة؟\nوَمَا ٱخۡتَلَفَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ بَغۡيَۢا بَيۡنَهُمۡۗ وَمَن يَكۡفُرۡ بَِٔايَٰتِ ٱللَّهِ فَإِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ ١٩\nإخبار أنهم اختلفوا بعد معرفتهم بالحقائق من أجل البغي؛ وهو الحسد. ابن جزي: ١/١٣٩.\nبينت الآية سببًا من أسباب الاختلاف، فما هو؟\nإِنَّ ٱلَّذِينَ يَكۡفُرُونَ بِٔاَيَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلنَّبِيِّۧنَ بِغَيۡرِ حَقّٖ وَيَقۡتُلُونَ ٱلَّذِينَ يَأۡمُرُونَ بِٱلۡقِسۡطِ مِنَ ٱلنَّاسِ فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٍ ٢١\nدلت هذه الآية على أن الأمر بالمعروف والنهي عن المنكر كان واجبًا في الأمم المتقدمة. القرطبي: ٥/٧٣.\nبيّن عظم شعيرة الأمر بالمعروف والنهي عن المنكر."],[53,"§آل عمران ، الواقعة\nwords\nتُولِجُتُدخِلُ.\nتَتَّقُوا مِنهُم تُقَاةًتُهَادِنُوهُمُ اتِّقَاءَ شَرِّهِم إِذَا كُنتُم ضِعَافًا.\ndeeds\nاسأل الله تعالى أن يستعملك في الخير؛ فإن الخير بيد الله تعالى يجريه على يد من يشاء من عباده.\nاكتب رسالة تحذر فيها من موالاة أعداء الله تعالى، وتنبه من اغتر بالكفار.\nادع الله تعالى أن يرزقك الإخلاص؛ فهو سبحانه عالم بما في قلبك.\nguid\nمن أعظم الجرم أن يُدعَى المؤمن للكتاب والسنة فيرفض حكمهما لهوى نفسه، والعياذ بالله.\nشدة نار جهنم وما فيها من العذاب البدني والنفسي.\nالافتراء على الدين، والابتداع فيه، والقول فيه بغير علم، من أكثر المفسدات للدين والعقيدة.\nالرزق بيد الله وحده، وما العبيد إلا وسائل يقدرها الله لإيصال هذا الرزق؛ فإذا سألت فأسال الله.\nrefl\nأَلَمۡ تَرَ إِلَى ٱلَّذِينَ أُوتُواْ نَصِيبٗا مِّنَ ٱلۡكِتَٰبِ يُدۡعَوۡنَ إِلَىٰ كِتَٰبِ ٱللَّهِ لِيَحۡكُمَ بَيۡنَهُمۡ ثُمَّ يَتَوَلَّىٰ فَرِيقٞ مِّنۡهُمۡ وَهُم مُّعۡرِضُونَ ٢٣\nما أنكرَ مُنكِرٌ حقًا وهو يعلمه إلا سلبه الله تعالى علمه حتى يصير إنكاره له بصورة وبوصف من لم يكن قط علِمَه. الألوسي: ٣/٥٠.\nما دلالة وصف الذين أوتوا الكتاب بالإعراض؟\nذَٰلِكَ بِأَنَّهُمۡ قَالُواْ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامٗا مَّعۡدُودَٰتٖۖ وَغَرَّهُمۡ فِي دِينِهِم مَّا كَانُواْ يَفۡتَرُونَ ٢٤\nانعدم اكتراثهم باتباع الحق؛ لأن اعتقادهم النجاة من عذاب الله على كل حال جرَّأهم على ارتكاب مثل هذا الإعراض. ابن عاشور: ٣/٢١١.\nماذا يترتب على اعتقاد المتكبرين أن النار لن تمسهم إلا أيامًا معدودات؟\nوَتُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَتُخۡرِجُ ٱلۡمَيِّتَ مِنَ ٱلۡحَيِّۖ\nوهذا أعظم دليل على قدرة الله، وأن جميع الأشياء مسخرة مدبرة، لا تملك من التدبير شيئًا؛ فخلقه تعالى الأضداد والضد من ضده بيان أنها مقهورة. السعدي: ١٢٧.\nكيف تدل الآية على كمال قدرة الله -سبحانه وتعالى- وضعف المخلوقات؟\nلَّا يَتَّخِذِ ٱلۡمُؤۡمِنُونَ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۖ وَمَن يَفۡعَلۡ ذَٰلِكَ فَلَيۡسَ مِنَ ٱللَّهِ فِي شَيۡءٍ إِلَّآ أَن تَتَّقُواْ مِنۡهُمۡ تُقَىٰةٗۗ\nالصحيح أن كل ما عدَّه العُرف تعظيمًا وحسبه المسلمون موالاةً فهو منهى عنه، ولو مع أهل الذمة؛ لا سيّما إذا أوقع شيئًا في قلوب ضعفاء المؤمنين. الألوسي: ٣/١٢٠.\nما صفة الموالاة المنهي عنها مع غير المسلمين؟\nقُلۡ إِن تُخۡفُواْ مَا فِي صُدُورِكُمۡ أَوۡ تُبۡدُوهُ يَعۡلَمۡهُ ٱللَّهُۗ وَيَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ٢٩\nوهذا من التهديد؛ إذ المهدد لا يحول بينه وبين تحقيق وعيده إلا أحد أمرين: الجهل بجريمة المجرم، أو العجز عنه؛ فلما أعلمهم بعموم علمه وعموم قدرته؛ علموا أن الله لا يفلتهم من عقابه. ابن عاشور: ٣/٢٢٢.\nلماذا جمع -سبحانه وتعالى- بين علمه وقدرته في هذه الآية؟\nقُلۡ إِن تُخۡفُواْ مَا فِي صُدُورِكُمۡ أَوۡ تُبۡدُوهُ يَعۡلَمۡهُ ٱللَّهُۗ وَيَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ٢٩\nوهذا تنبيه منه لعباده... لئلَّا يرتكبوا ما نهى عنه، وما يبغضه منهم؛ فإنه عالم بجميع أمورهم، وهو قادر على معاجلتهم بالعقوبة، وإن أنظر من أنظر منهم، فإنه يمهل ثم يأخذ أخذ عزيز مقتدر. ابن كثير: ١/٣٣٨.\nما الذي يفيده المسلم من معرفة علم الله الشامل وقدرته الكاملة؟\nقُلۡ إِن تُخۡفُواْ مَا فِي صُدُورِكُمۡ أَوۡ تُبۡدُوهُ يَعۡلَمۡهُ ٱللَّهُۗ وَيَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ٢٩\nففيه إرشاد إلى تطهير القلوب، واستحضار علم الله كل وقت؛ فيستحي العبد من ربه أن يرى قلبه محلًّا لكل فكر رديء، بل يشغل أفكاره فيما يقرب إلى الله من تدبر آية من كتاب، أو سنة من أحاديث رسول الله، أو تصور وبحث في علم ينفعه، أو تفكر في مخلوقات الله ونعمه، أو نصح لعباد الله. السعدي: ١٢٨.\nإذا تبين لك علم الله بما في قلبك، فما الحالة التي يجب أن تكون عليها؟"],[54,"§آل عمران\nwords\nنَذَرتُ لَكَجَعَلتُ لَكَ.\nمُحَرَّرًاخَالِصًا لِخِدمَةِ بَيتِ المَقدِسِ.\nأُعِيذُهَاأُحصِنُهَا.\nالرَّجِيمِالمَرجُومِ المُبعَدِ مِن رَحمَةِ اللهِ.\nالمِحرَابَمَكَانَ العِبَادَةِ.\ndeeds\nاعمل اليوم خيرًا من إطعام جائع، أو مساعدة محتاج، أو أي خير؛ فسوف تجده حاضرًا أمام عينك.\nابحث في القرآن عن ثلاثة من الأسباب الموجبة لمحبة الله تعالى، ثم اجتهد في تطبيقها لتنال محبة الله تعالى.\nأعذ نفسك وذريتك وأهلك بالله من الشيطان الرجيم.\nguid\nابتعد عن السيئات وأماكنها قبل أن تتمنى ذلك ولا تستطيعه.\nاتباع سنة الرسول -صلى الله عليه وسلم- الصحيحة هو الطريق الوحيد لنيل محبة الله تعالى.\nمن الفطرة أن الذكر غير الأنثى؛ فما كلف الله به الرجل من أعباء فهو متناسق مع طبيعة خلقته، وكذلك المرأة.\nrefl\nوَيُحَذِّرُكُمُ ٱللَّهُ نَفۡسَهُۥۗ وَٱللَّهُ رَءُوفُۢ بِٱلۡعِبَادِ ٣٠\nفالله -سبحانه وتعالى- منتقم ممن تعدى طوره ونسي أنه عبد. البقاعي: ٢/٦١.\nما دلالة قوله تعالى: ﴿وَيُحَذِّرُكُمُ ٱللَّهُ نَفۡسَهُۥۗ﴾؟\nوَيُحَذِّرُكُمُ ٱللَّهُ نَفۡسَهُۥۗ\nأعاد تعالى تحذيرنا نفسه رأفةً بنا ورحمةً؛ لئلَّا يطول علينا الأمد فتقسو قلوبنا، وليجمع لنا بين الترغيب الموجب للرجاء والعمل الصالح، والترهيب الموجب للخوف وترك الذنوب. السعدي: ١٢٨.\nلماذا أعاد الله تعالى تحذيرنا نفسه سبحانه؟\nقُلۡ إِن كُنتُمۡ تُحِبُّونَ ٱللَّهَ فَٱتَّبِعُونِي يُحۡبِبۡكُمُ ٱللَّهُ\nهذه الآية الكريمة حاكمة على كل من ادعى محبة الله وليس هو على الطريقة المحمدية؛ فإنه كاذب في نفس الأمر حتى يتبع الشرع المحمدي والدين النبوي في جميع أقواله وأفعاله. ابن كثير: ١/٣٣٨.\nفي الآية دليل على أهمية التحقق من صحة الأحاديث النبوية، وضح ذلك.\nقُلۡ إِن كُنتُمۡ تُحِبُّونَ ٱللَّهَ فَٱتَّبِعُونِي يُحۡبِبۡكُمُ ٱللَّهُ وَيَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ٣١\nوهذا لأن الرسول هو الذي يدعو إلى ما يحبه الله، وليس شيء يحبه الله إلا والرسول يدعو إليه، وليس شيء يدعو إليه الرسول إلا والله يحبه؛ فصار محبوب الرب ومدعو الرسول متلازمين. ابن تيمية: ٢/٦٠.\nلماذا كان اتباع الرسول -صلى الله عليه وسلم- علامة على محبة الله تعالى؟\nقُلۡ أَطِيعُواْ ٱللَّهَ وَٱلرَّسُولَۖ فَإِن تَوَلَّوۡاْ فَإِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡكَٰفِرِينَ ٣٢\nفدل على أن مخالفته في الطريقة كفر، والله لا يحب من اتصف بذلك وإن ادعى وزعم في نفسه أنه محب لله، ويتقرب إليه؛ حتى يتابع الرسول النبي الأمي خاتم الرسل. ابن كثير:١/٣٣٨.\nفي مخالفة النبي -صلى الله عليه وسلم- خطورة كبيرة، وضح ذلك من الآية.\nوَلَيۡسَ ٱلذَّكَرُ كَٱلۡأُنثَىٰۖ وَإِنِّي سَمَّيۡتُهَا مَرۡيَمَ\nفيه دلالة على تفضيل الذكر على الأنثى، وعلى التسمية وقت الولادة، وعلى أن للأم تسمية الولد إذا لم يكره الأب. السعدي: ١٢٩.\nاذكر بعض الفوائد من الآية.\nكُلَّمَا دَخَلَ عَلَيۡهَا زَكَرِيَّا ٱلۡمِحۡرَابَ وَجَدَ عِندَهَا رِزۡقٗاۖ قَالَ يَٰمَرۡيَمُ أَنَّىٰ لَكِ هَٰذَاۖ قَالَتۡ هُوَ مِنۡ عِندِ ٱللَّهِۖ إِنَّ ٱللَّهَ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٍ ٣٧\nيشعر بأنه عطاء متصل، فلا يتحدد ولا يتعدد؛ فهو رزق لا متعقب عليه. وأعظم الشكر لرزق الله -سبحانه وتعالى- معرفة العبد بأنه من الله تعالى. البقاعي: ٢/٧٥.\nما أعظم الشكر لرزق الله سبحانه؟"],[55,"§آل عمران\nwords\nلَدُنكَعِندِكَ.\nوَحَصُورًالاَ يَقرَبُ الذُّنُوبَ وَالشَّهَوَاتِ تَعَفُّفًا.\nعَاقِرٌعَقِيمٌ لاَ تَلِدُ.\nرَمزًاإِشَارَةً.\nيُلقُونَ أَقلاَمَهُميَطرَحُونَ سِهَامَهُم لِلاِقتِرَاعِ.\ndeeds\nادعُ اليوم بهذا الدعاء النبوي.\nحافظ على الأذكارفي الصباح والمساء وعقب الصلوات المفروضة.\nسبِّح الله تعالى هذا اليوم كثيرًا، وعلى كل أحوالك.\nguid\nإذا رأيت نعمة من الله على غيرك فادع الله بما تريد؛ فإن زكريا لمَّا رأى كرامة الله تعالى لمريم دعا بالولد، فاستُجيب له.\nاختر الأسماء ذات المعاني الحسنة، وسَمِّ بها أبناءك وبناتك؛ ودع الأسماء المستغربة والممجوجة.\nإذا اصطفى الله عبدًا لمهمة جليلة؛ عليه أن يقبل على الله تعالى شكرًا له، واستعانةً به على إتمامها، والصبر على أدائها.\nrefl\nهُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُۥۖ قَالَ رَبِّ هَبۡ لِي مِن لَّدُنكَ ذُرِّيَّةٗ طَيِّبَةًۖ إِنَّكَ سَمِيعُ ٱلدُّعَآءِ ٣٨\nوجاء الطلب بلفظ الهبة؛ لأن الهبة إحسان محض ليس في مقابلة شيء، وهو يناسب ما لا دخل فيه للوالد لكبر سنه، ولا للوالدة لكونها عاقرة لا تلد. الألوسي: ٣/١٤٤.\nلماذا جاء الطلب بلفظ الهبة؟\nفَنَادَتۡهُ ٱلۡمَلَٰٓئِكَةُ وَهُوَ قَآئِمٞ يُصَلِّي فِي ٱلۡمِحۡرَابِ أَنَّ ٱللَّهَ يُبَشِّرُكَ بِيَحۡيَىٰ\nواختلفوا في أنه لم سمي يحيى؟ فقال ابن عباس -رضي الله عنهما-: \"لأن الله أحيا به عقر أمه\"، و قال قتادة: \"لأن الله تعالى أحيا قلبه بالإيمان\"، وقيل: سمي يحيى لأنه استشهد، والشهداء أحياء. البغوي: ١/٣٤٨.\nلم سمى الله تعالى نبيه يحيى بهذا الاسم؟\nءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَةَ أَيَّامٍ إِلَّا رَمۡزٗاۗ\n﴿رَبِّ ٱجۡعَل لِّيٓ ءَايَةًۖ﴾ أي: علامة على وجود الولد. قال: ﴿ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَةَ أَيَّامٍ إِلَّا رَمۡزًاۗ﴾ أي: ينحبس لسانك عن كلامهم من غير آفة ولا سوء؛ فلا تقدر إلا على الإشارة والرمز. وهذا آية عظيمة أن لا تقدر على الكلام، وفيه مناسبة عجيبة؛ وهي أنه كما يمنع نفوذ الأسباب مع وجودها، فإنه يوجدها بدون أسبابها؛ ليدل ذلك أن الأسباب كلها مندرجة في قضائه وقدره. السعدي: ١٣٠\nفي انحباس لسان زكريا عن الكلام ومجيء ولده بعد عقم آيتان على قدرة الله، وضح ذلك\nإِنَّ ٱللَّهَ ٱصۡطَفَىٰكِ\nاختارها لكثرة عبادتها، وزهادتها، وشرفها، وطهارتها من الأكدار والوساوس. ابن كثير: ١/٣٤٢.\nما سبب اصطفاء الله لمريم بنت عمران؟\nيَٰمَرۡيَمُ ٱقۡنُتِي لِرَبِّكِ وَٱسۡجُدِي وَٱرۡكَعِي مَعَ ٱلرَّٰكِعِينَ ٤٣\nيراد بالركوع: الخشوع والتواضع؛ وكأن أمرها بذلك [حفظٌ] لها من الوقوع في مهاوي التكبر والاستعلاء بما لها من علو الدرجة. الألوسي: ٣/١٥٧.\nلماذا أمرت مريم -عليها السلام- بالسجود والركوع؟\nيَٰمَرۡيَمُ ٱقۡنُتِي لِرَبِّكِ وَٱسۡجُدِي وَٱرۡكَعِي مَعَ ٱلرَّٰكِعِينَ ٤٣\nوصوها بالمحافظة على الصلاة بعد أن أخبروها بعلو درجتها وكمال قربها إلى الله تعالى؛ لئلَّا تفتر، ولا تغفل عن العبادة. الألوسي: ٣/١٥٦.\nما دلالة قول الملائكة لمريم: ﴿وَٱسۡجُدِي وَٱرۡكَعِي مَعَ ٱلرَّٰكِعِينَ﴾؟\nوَٱسۡجُدِي وَٱرۡكَعِي مَعَ ٱلرَّٰكِعِينَ ٤٣\nخص السجود والركوع؛ لفضلهما، ودلالتهما على غاية الخضوع لله. السعدي: ١٣٠.\nلماذا خص السجود والركوع بالذكر؟"],[56,"§آل عمران\nwords\nالأَكمَهَمَن وُلِدَ أَعمَى.\nالحَوَارِيُّونَأَصفِيَاءُ عِيسَى -عليه السلام-.\ndeeds\nالعلم أساسه هبة وعطية من الله -سبحانه وتعالى-، وأعظمه العلم بكتاب الله؛ فاسأل الواهب أن يهبك ويرزقك علمًا نافعًا.\nأطل النظر والتأمل في آيات من كتاب الله؛ لعلك تؤتى الحكمة.\nحدد خطوات وابدأ بها للتعرف على أصدقاء يعينونك على طاعة الله.\nguid\nمن دوافع الداعية لهداية المدعوين: الشفقة والرحمة وحب الخير لهم.\nمن حكمة الداعية أن يكون له مجموعة من الأنصار؛ يربيهم، ويعلمهم، ويحملون الهم الدعوي معه.\nمن علامات أولياء الله تعالى: الوضوح في منهج حياتهم، وإعلانهم الصريح تبعيتهم لدين الله تعالى، ومناصرة المصلحين.\nrefl\nقَالَتۡ رَبِّ أَنَّىٰ يَكُونُ لِي وَلَدٞ وَلَمۡ يَمۡسَسۡنِي بَشَرٞۖ\nومن حكمة الباري تعالى أن تدرج بأخبار العباد من الغريب إلى ما هو أغرب منه؛ فذكر وجود يحيى بن زكريا بين أبوين أحدهما كبير، والآخر عاقر، ثم ذكر أغرب من ذلك وأعجب؛ وهو وجود عيسى -عليه السلام- من أم بلا أب؛ ليدل عباده أنه الفعال لما يريد، وأنه ما شاء كان وما لم يشأ لم يكن. السعدي: ١٣١.\nلماذا قدم قصة يحيى على قصة عيسى؟\nقَالَتۡ رَبِّ أَنَّىٰ يَكُونُ لِي وَلَدٞ وَلَمۡ يَمۡسَسۡنِي بَشَرٞۖ قَالَ كَذَٰلِكِ ٱللَّهُ يَخۡلُقُ مَا يَشَآءُۚ إِذَا قَضَىٰٓ أَمۡرٗا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ ٤٧\nوعبر عن تكوين الله لعيسى بفعل يخلق؛ لأنه إيجاد كائن من غير الأسباب المعتادة لإيجاد مثله؛ فهو خَلقٌ أُنُفٌ غير ناشئ عن أسباب إيجاد الناس، فكان لفعل يخلق هنا موقع متعين؛ فإن الصانع إذا صنع شيئًا من مواد معتادة وصنعة معتادة لا يقول: خلقت، وإنَّما يقول: صنعت. ابن عاشور: ٣/٢٤٩.\nلماذا عبرت الآية الكريمة بفعل (يخلق) بدلًا من (يصنع)؟\nوَأُبۡرِئُ ٱلۡأَكۡمَهَ وَٱلۡأَبۡرَصَ وَأُحۡيِ ٱلۡمَوۡتَىٰ بِإِذۡنِ ٱللَّهِۖ\nقال كثير من العلماء: بعث الله كل نبي من الأنبياء بما يناسب أهل زمانه... وأمَّا عيسى -عليه السلام- فبعث في زمن الأطباء وأصحاب علم الطبيعة؛ فجاءهم من الآيات بما لا سبيل لأحد إليه إلا أن يكون مؤيدًا من الذي شرع الشريعة، فمن أين للطبيب قدرة على إحياء الجماد، أو على مداواة الأكمه والأبرص، وبعث من هو في قبره رهين إلى يوم التناد. ابن كثير: ٢/٣٧.\nمن حكمة الله مخاطبة الناس بما يعرفون. وضِّح ذلك من خلال معجزة عيسى -عليه السلام-.\nوَأُبۡرِئُ ٱلۡأَكۡمَهَ وَٱلۡأَبۡرَصَ\nوإنَّما خص هذين؛ لأنهما داءان عياءان، وكان الغالب في زمن عيسى -عليه السلام- الطب، فأراهم المعجزة من جنس ذلك. البغوي: ١/٣٥٤.\nلم خص الله تعالى عيسى -عليه السلام- بهذه المعجزة؟\nوَلِأُحِلَّ لَكُم بَعۡضَ ٱلَّذِي حُرِّمَ عَلَيۡكُمۡۚ\nأصل دين اليهود فيه آصار وأغلال من التحريمات؛ ولهذا قال لهم المسيح: ﴿وَلِأُحِلَّ لَكُم بَعۡضَ ٱلَّذِي حُرِّمَ عَلَيۡكُمۡۚ﴾. ابن تيمية: ٢/٦٩.\nاتصفت شريعة اليهود بصفة، فما هي؟\nوَلِأُحِلَّ لَكُم بَعۡضَ ٱلَّذِي حُرِّمَ عَلَيۡكُمۡۚ وَجِئۡتُكُم بِٔاَيَةٖ مِّن رَّبِّكُمۡ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ ٥٠\n﴿فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ﴾: الأدب مع المحسن آكد، والخوف منه أحق وأوجب؛ لئلَّا يقطع إحسانه، ويبدل امتنانه. البقاعي: ٢/٩٤\nما دلالة تقديم إحسان الله سبحانه على الأمر بالتقوى؟\nإِنَّ ٱللَّهَ رَبِّي وَرَبُّكُمۡ فَٱعۡبُدُوهُۚ هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ ٥١\nلا أدعوكم إلى شيء إلا كنت أول فاعل له، ولا أدعي أني إله، ولا أدعو إلى عبادة غير الله تعالى كما يدعي الدجال وغيره من الكذبة الذين تظهر الخوارق على أيديهم امتحانًا من الله -سبحانه وتعالى- لعباده، فيجعلونها سببًا للعلو في الأرض، والترفع على الناس. البقاعي: ٢/٩٤.\nما دلالة تقديم ربي على ربكم؟"],[57,"§آل عمران\nwords\nمُتَوَفِّيكَقَابِضُكَ مِنَ الأَرضِ.\nنَبتَهِلنَدعُ بِاللَّعنَةِ عَلَى الكَاذِبِ مِنَّا.\ndeeds\nحدد حاجة من حاجاتك، ثم انظر إلى عبادة تقوم بها، وتوسل إلى الله تعالى بتلك العبادة.\nاقرأ الأحاديث المتعلقة بعلامات الساعة الكبرى من أحد كتب الحديث الصحيح.\nابحث عن قضية أشكل عليك فهمها، ثم ابحث في القرآن عن آيات تتكلم عنها، لعلك تهتدي إلى الحق فيها.\nguid\nلا تحزن لكثرة ما يحاك للدين وأهله من المؤامرات والمكائد؛ فإن الله سبحانه حافظ لدينه وأوليائه.\nاحذر أن تكون موغلًا في معصية الله تعالى، ونعم الله تنساق إليك؛ فإن هذا مكر واستدراج بك للهلاك، نعوذ بالله من ذلك.\nإياك والخصومة والجدال بلا بينة؛ فإنك محاسب عليها.\nrefl\nرَبَّنَآ ءَامَنَّا بِمَآ أَنزَلۡتَ وَٱتَّبَعۡنَا ٱلرَّسُولَ فَٱكۡتُبۡنَا مَعَ ٱلشَّٰهِدِينَ ٥٣\n﴿مَعَ ٱلشَّٰهِدِينَ﴾: أي مع الذين يشهدون بالحق من الأمم، وقيل مع أمة محمد -صلى الله عليه وسلم-. ابن جزي: ١/١٤٧\nما الذي ينبغي عليك فعله حتى تكون ممن تشملك هذه الدعوة؟\nوَمَكَرُواْ وَمَكَرَ ٱللَّهُۖ وَٱللَّهُ خَيۡرُ ٱلۡمَٰكِرِينَ ٥٤\nومكرُ الله: استدراجه لعباده من حيث لا يعلمون... قال ابن عباس -رضي الله عنهما-: \"كلما أحدثوا خطيئة جددنا لهم نعمة\". القرطبي: ٥/١٥١.\nبينت الآية نوعًا من مكر الله تعالى بالعبد، فما هو؟\nوَجَاعِلُ ٱلَّذِينَ ٱتَّبَعُوكَ فَوۡقَ ٱلَّذِينَ كَفَرُوٓاْ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۖ\nأي: بالحجة وإقامة البرهان، وقيل: بالعز والغلبة. القرطبي: ٥/١٥٦.\nكيف يكون علو أهل التوحيد على غيرهم؟\nوَجَاعِلُ ٱلَّذِينَ ٱتَّبَعُوكَ فَوۡقَ ٱلَّذِينَ كَفَرُوٓاْ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۖ ثُمَّ إِلَيَّ مَرۡجِعُكُمۡ فَأَحۡكُمُ بَيۡنَكُمۡ فِيمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ ٥٥\nهم أهل الإسلام الذين صدقوه، واتبعوا دينه في التوحيد من أمة محمد -صلى الله عليه وسلم-؛ فهم فوق الذين كفروا؛ ظاهرين قاهرين؛ بالعزة والمنعة والحجة. البغوي: ١/٣٦١.\nوعد الله أتباع عيسى -عليه السلام- بالنصر والتمكين، فهل يشمل ذلك أمة محمد -صلى الله عليه وسلم-؟ وضح ذلك.\nوَأَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فَيُوَفِّيهِمۡ أُجُورَهُمۡۗ\nدل ذلك على أنه يحصل لهم في الدنيا ثواب لأعمالهم من: الإكرام، والإعزاز، والنصر، والحياة الطيبة، وإنَّما توفية الأجور يوم القيامة يجدون ما قدموه من الخيرات محضرًا موفرًا؛ فيعطي منهم كل عامل أجر عمله، ويزيدهم من فضله وكرمه. السعدي: ١٣٢.\nكيف تدل هذه الآية على حصول الأجر للمؤمنين في الدنيا والآخرة؟\nإِنَّ مَثَلَ عِيسَىٰ عِندَ ٱللَّهِ كَمَثَلِ ءَادَمَۖ خَلَقَهُۥ مِن تُرَابٖ ثُمَّ قَالَ لَهُۥ كُن فَيَكُونُ ٥٩\nالآية حجة على النصارى في قولهم: كيف يكون ابن دون أب، فمثله الله بآدم الذي خلقه الله دون أم ولا أب؛ وذلك أغرب مما استبعدوه؛ فهو أقطع لقولهم. ابن جزي: ١/١٤٧.\nفي هذه الآية رد قاطع على النصارى، بينه باختصار؟\nٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُن مِّنَ ٱلۡمُمۡتَرِينَ ٦٠\nوفي هذه الآية وما بعدها دليل على قاعدة شريفة، وهو: أن ما قامت الأدلة على أنه حق، وجزم به العبد من مسائل العقائد وغيرها؛ فإنه يجب أن يجزم بأن كل ما عارضه فهو باطل، وكل شبهة تورد عليه فهي فاسدة، سواء قدر العبد على حلها أم لا، فلا يوجب له عجزه على حلها القدح فيما علمه؛ لأن ما خالف الحق فهو باطل، قال تعالى: ﴿فَمَاذَا بَعۡدَ ٱلۡحَقِّ إِلَّا ٱلضَّلَٰلُ﴾، وبهذه القاعدة الشرعية تنحلُّ عن الإنسان إشكالات كثيرة يوردها المتكلمون، ويرتبها المنطقيون؛ إن حلها الإنسان فهو تبرع منه، وإلا فوظيفته أن يبين الحق بأدلته ويدعو إليه. السعدي: ١٣٣.\nكيف يتعامل المسلم الموحد مع الشبهات التي تطرح عليه في المسائل العقدية التي دلالتها واضحة وصريحة من الكتاب والسنة؟"],[58,"§آل عمران\nwords\nكَلِمَةٍ سَوَاءٍكَلِمَةِ عَدلٍ وَحَقٍّ نَلتَزِمُ بِهَا.\nحَنِيفًامَائِلًا عَنِ الشِّركِ قَصدًا.\ndeeds\nابدأ اليوم بوضع برنامج لنفسك في قراءة قصص القرآن، مع جمعك للدروس والعبر منها.\nأرسل لبعض الكفار عبر النت ترجمة معاني هذه الآية الكريمة وتفسيرها بلغتهم.\nاكتب مقالًا في آداب الحوار المحمود من خلال تتبع الآيات، وأرسله إلى زملائك.\nguid\nإذا رأيت فساد أهل الضلال قد استفحل، وشرهم قد استطار؛ فتذكر أن الله تعالى يعلم ذلك كله، وسيجازيهم عليه.\nالأنبياء معصومون فيما يبلغون عن ربهم، ومن ادعى العصمة غيرهم فهو كاذب، وقد يوصله أتباعه إلى مقام الربوبية -والعياذ بالله-.\nالمحاججة إنَّما تكون فيما لك به علم، أما الأشياء التي لا علم لك بها فلا تجادل فيها ولا تنازع.\nrefl\nقُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ تَعَالَوۡاْ إِلَىٰ كَلِمَةٖ سَوَآءِۢ بَيۡنَنَا وَبَيۡنَكُمۡ أَلَّا نَعۡبُدَ إِلَّا ٱللَّهَ وَلَا نُشۡرِكَ بِهِۦ شَيۡٔاً وَلَا يَتَّخِذَ بَعۡضُنَا بَعۡضًا أَرۡبَابٗا مِّن دُونِ ٱللَّهِۚ\nولعل الفائدة في ذلك: أنكم إذا قلتم لهم ذلك -وأنتم أهل العلم على الحقيقة- كان ذلك زيادة على إقامة الحجة عليهم، كما استشهد تعالى بأهل العلم حجةً على المعاندين. السعدي: ١٣٤.\nما الفائدة من دعوة أهل الكتاب إلى كلمة سواء؟\nقُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ تَعَالَوۡاْ إِلَىٰ كَلِمَةٖ سَوَآءِۢ بَيۡنَنَا وَبَيۡنَكُمۡ أَلَّا نَعۡبُدَ إِلَّا ٱللَّهَ وَلَا نُشۡرِكَ بِهِۦ شَيۡٔاً وَلَا يَتَّخِذَ بَعۡضُنَا بَعۡضًا أَرۡبَابٗا مِّن دُونِ ٱللَّهِۚ\nالتوحيد -وإن كان أصل الصلاح- فهو أعظم العدل. ابن تيمية: ٢/٨٠.\nالتوحيد أعظم العدل، بين ذلك.\nوَلَا يَتَّخِذَ بَعۡضُنَا بَعۡضًا أَرۡبَابٗا مِّن دُونِ ٱللَّهِۚ فَإِن تَوَلَّوۡاْ فَقُولُواْ ٱشۡهَدُواْ بِأَنَّا مُسۡلِمُونَ ٦٤\nوفيه رد على الروافض الذين يقولون: يجب قبول قول الإمام دون إبانة مستند شرعي، وأنه يحل ما حرمه الله من غير أن يبين مستندًا من الشريعة. القرطبي: ٥/١٦٢.\nكيف ترد على الروافض من خلال هذه الآية؟\nهَٰٓأَنتُمۡ هَٰٓؤُلَآءِ حَٰجَجۡتُمۡ فِيمَا لَكُم بِهِۦ عِلۡمٞ فَلِمَ تُحَآجُّونَ فِيمَا لَيۡسَ لَكُم بِهِۦ عِلۡمٞۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ ٦٦\nفي الآية دليل على المنع من الجدال لمن لا علم له، والحظر على من لا تحقيق عنده. القرطبي: ٥/١٦٥.\nمن الذي يحق له الجدال والنقاش في المسائل العلمية؟\nمَا كَانَ إِبۡرَٰهِيمُ يَهُودِيّٗا وَلَا نَصۡرَانِيّٗا وَلَٰكِن كَانَ حَنِيفٗا مُّسۡلِمٗا وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ ٦٧\nفيها أيضًا حث على علم التاريخ، وأنه طريق لرد كثير من الأقوال الباطلة، والدعاوى التي تخالف ما علم من التاريخ. السعدي: ١٣٤.\nما أهمية علم التاريخ بالنسبة لطالب العلم الشرعي؟\nوَدَّت طَّآئِفَةٞ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ لَوۡ يُضِلُّونَكُمۡ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمۡ وَمَا يَشۡعُرُونَ ٦٩\nقيل: إن معنى إضلالهم أنفسهم إصرارهم على الضلال بما سولت لهم أنفسهم، مع تمكنهم من اتباع الهدى بإيضاح الحجج. الألوسي: ٣/١٩٩.\nكيف يضل الإنسان نفسه؟\nوَدَّت طَّآئِفَةٞ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ لَوۡ يُضِلُّونَكُمۡ\nومن المعلوم أنه من وَدَّ شيئًا سعى بجهده على تحصيل مراده؛ فهذه الطائفة تسعى وتبذل جهدها في رد المؤمنين، وإدخال الشُّبَه عليهم بكل طريق يقدرون عليه. السعدي: ١٣٤.\nما الذي يوده أهل الكتاب للمسلمين؟"]])